@dataclass
class DimensionalProjectionConfig:
    """Configuration for dimensional projection algorithms"""
    source_dimensions: int
    target_dimensions: int
    projection_method: str
    manifold_learning_params: Dict[str, Any] = field(default_factory=dict)
    optimization_params: Dict[str, Any] = field(default_factory=dict)
    validation_params: Dict[str, Any] = field(default_factory=dict)
    computational_resources: Dict[str, Any] = field(default_factory=dict)

@dataclass
class HigherDimensionalData:
    """Container for higher-dimensional volcanic data"""
    data_id: str
    original_data: np.ndarray
    projected_data: np.ndarray
    dimension_mapping: Dict[int, str]
    projection_metadata: Dict[str, Any]
    quality_metrics: Dict[str, float]
    timestamp: datetime = field(default_factory=datetime.now)

@dataclass
class DimensionalPattern:
    """Represents a pattern discovered in higher-dimensional space"""
