    geometric_properties: Optional[Dict[str, float]] = None
    temporal_evolution: Optional[List[Dict[str, Any]]] = None
    causal_relationships: Optional[List[str]] = None
    uncertainty_bounds: Optional[Tuple[float, float]] = None
    validation_metrics: Dict[str, float] = field(default_factory=dict)

