class HigherDimensionalProjectionEngine:
    """
    Advanced engine for projecting volcanic data into higher-dimensional spaces
    using sophisticated mathematical algorithms and manifold learning techniques.
    """
    
    def __init__(self, database_manager: DatabaseManager):
        self.db_manager = database_manager
        self.data_connector = RealDataConnector(database_manager)
        
        # Initialize projection algorithms
        self.projection_algorithms = {
            'pca': PCA,
            'kernel_pca': KernelPCA,
            'ica': FastICA,
            'factor_analysis': FactorAnalysis,
            'tsne': TSNE,
            'isomap': Isomap,
            'lle': LocallyLinearEmbedding,
            'spectral': SpectralEmbedding
        }
        
        # Add UMAP if available
        if UMAP_AVAILABLE:
            self.projection_algorithms['umap'] = umap.UMAP
        
        # Add PHATE if available
        if PHATE_AVAILABLE:
            self.projection_algorithms['phate'] = phate.PHATE
        
        # Initialize scalers
        self.scalers = {
            'standard': StandardScaler,
            'robust': RobustScaler,
            'minmax': MinMaxScaler
        }
        
        logger.info("Higher-Dimensional Projection Engine initialized")
    
    async def project_volcanic_data_to_higher_dimensions(
        self,
        volcanic_data: np.ndarray,
        config: DimensionalProjectionConfig
    ) -> HigherDimensionalData:
        """
        Project volcanic data into higher-dimensional spaces using advanced algorithms.
        
        Args:
            volcanic_data: Input volcanic data matrix
            config: Projection configuration parameters
            
        Returns:
            HigherDimensionalData object with projection results
        """
        try:
            logger.info(f"Starting higher-dimensional projection with method: {config.projection_method}")
            
            # Validate input data
            if volcanic_data.shape[1] < config.source_dimensions:
                raise ValueError(f"Input data has {volcanic_data.shape[1]} dimensions, need at least {config.source_dimensions}")
            
            # Preprocess data
            preprocessed_data = await self._preprocess_volcanic_data(volcanic_data, config)
            
            # Apply dimensional projection
            projected_data = await self._apply_projection_algorithm(preprocessed_data, config)
            
            # Calculate quality metrics
            quality_metrics = await self._calculate_projection_quality(
                preprocessed_data, projected_data, config
            )
            
            # Create dimension mapping
            dimension_mapping = await self._create_dimension_mapping(config)
            
            # Generate projection metadata
            projection_metadata = {
                'algorithm': config.projection_method,
                'parameters': config.manifold_learning_params,
                'preprocessing': 'standard_robust_scaling',
                'computational_time': quality_metrics.get('computation_time', 0),
                'memory_usage': quality_metrics.get('memory_usage', 0)
            }
            
            # Create result object
            result = HigherDimensionalData(
                data_id=f"proj_{datetime.now().strftime('%Y%m%d_%H%M%S')}",
                original_data=volcanic_data,
                projected_data=projected_data,
                dimension_mapping=dimension_mapping,
                projection_metadata=projection_metadata,
                quality_metrics=quality_metrics
            )
            
            # Store results in database
            await self._store_projection_results(result)
            
            logger.info(f"Higher-dimensional projection completed successfully")
            return result
            
        except Exception as e:
            logger.error(f"Error in higher-dimensional projection: {str(e)}")
            raise  
  
    async def _preprocess_volcanic_data(
        self,
        data: np.ndarray,
        config: DimensionalProjectionConfig
    ) -> np.ndarray:
        """Advanced preprocessing for volcanic data before projection"""
        
        # Handle missing values using advanced imputation
        if np.isnan(data).any():
            from sklearn.impute import KNNImputer
            imputer = KNNImputer(n_neighbors=5)
            data = imputer.fit_transform(data)
        
        # Remove outliers using multiple methods
        outlier_detectors = [
            IsolationForest(contamination=0.1, random_state=42),
            LocalOutlierFactor(n_neighbors=20, contamination=0.1)
        ]
        
        outlier_mask = np.ones(data.shape[0], dtype=bool)
        for detector in outlier_detectors:
            if hasattr(detector, 'fit_predict'):
                outliers = detector.fit_predict(data) == -1
                outlier_mask &= ~outliers
        
        clean_data = data[outlier_mask]
        
        # Apply robust scaling
        scaler = RobustScaler()
        scaled_data = scaler.fit_transform(clean_data)
        
        # Apply feature selection for high-dimensional data
        if scaled_data.shape[1] > 50:
            from sklearn.feature_selection import SelectKBest, f_regression
            selector = SelectKBest(score_func=f_regression, k=min(50, scaled_data.shape[1]))
            scaled_data = selector.fit_transform(scaled_data, np.arange(scaled_data.shape[0]))
        
        return scaled_data
    
    async def _apply_projection_algorithm(
        self,
        data: np.ndarray,
        config: DimensionalProjectionConfig
    ) -> np.ndarray:
        """Apply the specified projection algorithm with optimization"""
        
        algorithm_name = config.projection_method.lower()
        
        if algorithm_name not in self.projection_algorithms:
            raise ValueError(f"Unknown projection algorithm: {algorithm_name}")
        
        # Get algorithm class and parameters
        AlgorithmClass = self.projection_algorithms[algorithm_name]
        params = config.manifold_learning_params.copy()
        
        # Set target dimensions
        if algorithm_name in ['pca', 'kernel_pca', 'ica', 'factor_analysis']:
            params['n_components'] = config.target_dimensions
        elif algorithm_name in ['tsne', 'umap', 'isomap', 'lle', 'spectral']:
            params['n_components'] = config.target_dimensions
        elif algorithm_name == 'phate':
            params['n_components'] = config.target_dimensions
        
        # Advanced algorithm-specific optimizations with adaptive parameter selection
        if algorithm_name == 'tsne':
            # Adaptive t-SNE parameters based on data characteristics
            optimal_params = await self._optimize_tsne_parameters(data, config)
            params.update(optimal_params)
        elif algorithm_name == 'umap' and UMAP_AVAILABLE:
            # Adaptive UMAP parameters
            optimal_params = await self._optimize_umap_parameters(data, config)
            params.update(optimal_params)
        elif algorithm_name == 'kernel_pca':
            # Adaptive kernel selection and parameter optimization
            optimal_params = await self._optimize_kernel_pca_parameters(data, config)
            params.update(optimal_params)
        elif algorithm_name == 'isomap':
            # Adaptive Isomap parameters
            optimal_params = await self._optimize_isomap_parameters(data, config)
            params.update(optimal_params)
        elif algorithm_name == 'lle':
            # Adaptive LLE parameters
            optimal_params = await self._optimize_lle_parameters(data, config)
            params.update(optimal_params)
        elif algorithm_name == 'spectral':
            # Adaptive spectral embedding parameters
            optimal_params = await self._optimize_spectral_parameters(data, config)
            params.update(optimal_params)
        
        # Initialize and fit algorithm
        algorithm = AlgorithmClass(**params)
        
        if hasattr(algorithm, 'fit_transform'):
            projected_data = algorithm.fit_transform(data)
        else:
            algorithm.fit(data)
            projected_data = algorithm.transform(data)
        
        return projected_data
    
    async def _optimize_tsne_parameters(self, data: np.ndarray, config: DimensionalProjectionConfig) -> Dict[str, Any]:
        """Optimize t-SNE parameters using adaptive methods"""
        try:
            n_samples = data.shape[0]
            
            # Adaptive perplexity based on data size and local density
            distances = pdist(data)
            median_distance = np.median(distances)
            
            # Estimate local density to adjust perplexity
            from sklearn.neighbors import NearestNeighbors
            k = min(30, n_samples // 4)
            nbrs = NearestNeighbors(n_neighbors=k+1).fit(data)
            knn_distances, _ = nbrs.kneighbors(data)
            mean_knn_distance = np.mean(knn_distances[:, k])
            
            # Adaptive perplexity: higher for denser data
            density_factor = median_distance / (mean_knn_distance + 1e-10)
            base_perplexity = min(30, max(5, n_samples // 4))
            adaptive_perplexity = int(base_perplexity * min(2.0, density_factor))
            
            # Adaptive learning rate based on data dimensionality
            base_learning_rate = max(10, n_samples / 12)
            dimension_factor = np.log(data.shape[1] + 1)
            adaptive_learning_rate = base_learning_rate * dimension_factor
            
            # Adaptive number of iterations
            complexity_factor = np.log(n_samples) * np.log(data.shape[1])
            base_iterations = 1000
            adaptive_iterations = int(base_iterations * min(3.0, complexity_factor / 10))
            
            return {
                'perplexity': adaptive_perplexity,
                'learning_rate': adaptive_learning_rate,
                'n_iter': adaptive_iterations,
                'early_exaggeration': 12.0,
                'min_grad_norm': 1e-7,
                'method': 'barnes_hut' if n_samples > 1000 else 'exact'
            }
            
        except Exception as e:
            logger.warning(f"t-SNE parameter optimization failed: {str(e)}")
            return {
                'perplexity': min(30, data.shape[0] // 4),
                'n_iter': 1000,
                'learning_rate': 200
            }
    
    async def _optimize_umap_parameters(self, data: np.ndarray, config: DimensionalProjectionConfig) -> Dict[str, Any]:
        """Optimize UMAP parameters using adaptive methods"""
        try:
            n_samples = data.shape[0]
            
            # Adaptive n_neighbors based on intrinsic dimensionality
            intrinsic_dim = await self._estimate_intrinsic_dimensionality(data)
            
            # Scale neighbors with intrinsic dimension and sample size
            base_neighbors = int(np.sqrt(n_samples))
            dimension_scaling = np.log(intrinsic_dim + 1)
            adaptive_neighbors = max(5, min(50, int(base_neighbors * dimension_scaling)))
            
            # Adaptive min_dist based on data spread
            distances = pdist(data)
            data_spread = np.std(distances)
            adaptive_min_dist = max(0.001, min(0.5, data_spread / 100))
            
            # Adaptive metric selection based on data characteristics
            if data.shape[1] > 50:
                metric = 'cosine'  # Better for high-dimensional data
            elif intrinsic_dim < 3:
                metric = 'euclidean'  # Good for low-dimensional manifolds
            else:
                metric = 'manhattan'  # Robust for medium dimensions
            
            # Adaptive spread based on target dimensions
            adaptive_spread = max(1.0, config.target_dimensions * 0.5)
            
            return {
                'n_neighbors': adaptive_neighbors,
                'min_dist': adaptive_min_dist,
                'metric': metric,
                'spread': adaptive_spread,
                'n_epochs': max(200, n_samples // 10),
                'learning_rate': 1.0,
                'repulsion_strength': 1.0,
                'negative_sample_rate': 5
            }
            
        except Exception as e:
            logger.warning(f"UMAP parameter optimization failed: {str(e)}")
            return {
                'n_neighbors': min(15, data.shape[0] // 10),
                'min_dist': 0.1,
                'metric': 'euclidean'
            }
    
    async def _optimize_kernel_pca_parameters(self, data: np.ndarray, config: DimensionalProjectionConfig) -> Dict[str, Any]:
        """Optimize Kernel PCA parameters using cross-validation"""
        try:
            # Test multiple kernels and parameters
            kernel_candidates = [
                ('rbf', {'gamma': 'scale'}),
                ('rbf', {'gamma': 'auto'}),
                ('rbf', {'gamma': 1.0 / data.shape[1]}),
                ('poly', {'degree': 2, 'gamma': 'scale'}),
                ('poly', {'degree': 3, 'gamma': 'scale'}),
                ('sigmoid', {'gamma': 'scale', 'coef0': 0.0}),
                ('cosine', {})
            ]
            
            best_score = -np.inf
            best_params = {'kernel': 'rbf', 'gamma': 1.0 / data.shape[1]}
            
            # Use reconstruction error as optimization criterion
            for kernel, kernel_params in kernel_candidates:
                try:
                    # Create temporary KernelPCA
                    temp_kpca = KernelPCA(
                        n_components=config.target_dimensions,
                        kernel=kernel,
                        **kernel_params,
                        eigen_solver='auto',
                        fit_inverse_transform=True
                    )
                    
                    # Fit and transform
                    transformed = temp_kpca.fit_transform(data)
                    
                    # Compute reconstruction error if possible
                    if hasattr(temp_kpca, 'inverse_transform'):
                        try:
                            reconstructed = temp_kpca.inverse_transform(transformed)
                            reconstruction_error = np.mean(np.linalg.norm(data - reconstructed, axis=1))
                            score = -reconstruction_error  # Negative because we want to minimize error
                        except:
                            # Use explained variance proxy
                            score = np.sum(np.var(transformed, axis=0))
                    else:
                        # Use explained variance as score
                        score = np.sum(np.var(transformed, axis=0))
                    
                    if score > best_score:
                        best_score = score
                        best_params = {'kernel': kernel, **kernel_params}
                        
                except Exception as e:
                    logger.warning(f"Kernel {kernel} evaluation failed: {str(e)}")
                    continue
            
            # Add additional optimized parameters
            best_params.update({
                'eigen_solver': 'auto',
                'tol': 1e-6,
                'max_iter': None,
                'remove_zero_eig': True
            })
            
            return best_params
            
        except Exception as e:
            logger.warning(f"Kernel PCA parameter optimization failed: {str(e)}")
            return {
                'kernel': 'rbf',
                'gamma': 1.0 / data.shape[1]
            }
    
    async def _optimize_isomap_parameters(self, data: np.ndarray, config: DimensionalProjectionConfig) -> Dict[str, Any]:
        """Optimize Isomap parameters using geodesic distance analysis"""
        try:
            n_samples = data.shape[0]
            
            # Optimize number of neighbors using geodesic distance preservation
            neighbor_candidates = [5, 10, 15, 20, min(30, n_samples // 5)]
            best_neighbors = 10
            best_score = -np.inf
            
            for n_neighbors in neighbor_candidates:
                if n_neighbors >= n_samples:
                    continue
                    
                try:
                    # Test connectivity and geodesic distance quality
                    from sklearn.neighbors import kneighbors_graph
                    from scipy.sparse.csgraph import connected_components, shortest_path
                    
                    # Build k-NN graph
                    knn_graph = kneighbors_graph(data, n_neighbors=n_neighbors, mode='distance')
                    
                    # Check connectivity
                    n_components, labels = connected_components(knn_graph, directed=False)
                    
                    if n_components == 1:  # Graph is connected
                        # Compute geodesic distances
                        geodesic_distances = shortest_path(knn_graph, method='dijkstra')
                        
                        # Check for reasonable geodesic distances (not too many infinities)
                        finite_distances = geodesic_distances[np.isfinite(geodesic_distances)]
                        
                        if len(finite_distances) > 0.8 * geodesic_distances.size:
                            # Score based on geodesic distance distribution
                            euclidean_distances = pdist(data)
                            geodesic_flat = geodesic_distances[np.triu_indices_from(geodesic_distances, k=1)]
                            geodesic_finite = geodesic_flat[np.isfinite(geodesic_flat)]
                            
                            if len(geodesic_finite) > 0:
                                # Correlation between Euclidean and geodesic distances
                                euclidean_sample = euclidean_distances[:len(geodesic_finite)]
                                correlation = np.corrcoef(euclidean_sample, geodesic_finite)[0, 1]
                                
                                # Score: high correlation but not too high (indicates manifold structure)
                                score = correlation * (1 - correlation)  # Maximized around 0.5
                                
                                if score > best_score:
                                    best_score = score
                                    best_neighbors = n_neighbors
                                    
                except Exception as e:
                    logger.warning(f"Isomap neighbor evaluation {n_neighbors} failed: {str(e)}")
                    continue
            
            # Adaptive path method selection
            if n_samples > 1000:
                path_method = 'FW'  # Floyd-Warshall for large datasets
            else:
                path_method = 'D'   # Dijkstra for smaller datasets
            
            return {
                'n_neighbors': best_neighbors,
                'path_method': path_method,
                'neighbors_algorithm': 'auto',
                'n_jobs': -1
            }
            
        except Exception as e:
            logger.warning(f"Isomap parameter optimization failed: {str(e)}")
            return {
                'n_neighbors': min(10, data.shape[0] // 5),
                'path_method': 'auto'
            }
    
    async def _optimize_lle_parameters(self, data: np.ndarray, config: DimensionalProjectionConfig) -> Dict[str, Any]:
        """Optimize LLE parameters using reconstruction error analysis"""
        try:
            n_samples = data.shape[0]
            
            # Optimize number of neighbors for LLE
            neighbor_candidates = [5, 8, 12, 15, min(20, n_samples // 5)]
            best_neighbors = 8
            best_score = np.inf
            
            for n_neighbors in neighbor_candidates:
                if n_neighbors >= n_samples or n_neighbors <= config.target_dimensions:
                    continue
                    
                try:
                    # Test LLE reconstruction quality
                    temp_lle = LocallyLinearEmbedding(
                        n_neighbors=n_neighbors,
                        n_components=config.target_dimensions,
                        method='standard',
                        random_state=42
                    )
                    
                    # Fit and compute reconstruction error
                    temp_lle.fit(data)
                    reconstruction_error = temp_lle.reconstruction_error_
                    
                    if reconstruction_error < best_score:
                        best_score = reconstruction_error
                        best_neighbors = n_neighbors
                        
                except Exception as e:
                    logger.warning(f"LLE neighbor evaluation {n_neighbors} failed: {str(e)}")
                    continue
            
            # Select LLE method based on data characteristics
            if data.shape[1] > 10:
                method = 'modified'  # Better for high-dimensional data
            elif n_samples > 1000:
                method = 'hessian'   # Good for large datasets
            else:
                method = 'standard'  # Default method
            
            # Adaptive regularization
            reg = max(1e-6, 1e-3 / np.sqrt(n_samples))
            
            return {
                'n_neighbors': best_neighbors,
                'method': method,
                'reg': reg,
                'eigen_solver': 'auto',
                'tol': 1e-6,
                'max_iter': 100,
                'random_state': 42
            }
            
        except Exception as e:
            logger.warning(f"LLE parameter optimization failed: {str(e)}")
            return {
                'n_neighbors': min(8, data.shape[0] // 5),
                'method': 'standard'
            }
    
    async def _optimize_spectral_parameters(self, data: np.ndarray, config: DimensionalProjectionConfig) -> Dict[str, Any]:
        """Optimize Spectral Embedding parameters using eigenvalue analysis"""
        try:
            n_samples = data.shape[0]
            
            # Test different affinity methods
            affinity_candidates = [
                ('nearest_neighbors', {'n_neighbors': 10}),
                ('nearest_neighbors', {'n_neighbors': 15}),
                ('rbf', {'gamma': 1.0}),
                ('rbf', {'gamma': 'auto'})
            ]
            
            best_affinity = 'nearest_neighbors'
            best_params = {'n_neighbors': 10}
            best_score = -np.inf
            
            for affinity, affinity_params in affinity_candidates:
                try:
                    # Create temporary spectral embedding
                    temp_spectral = SpectralEmbedding(
                        n_components=config.target_dimensions,
                        affinity=affinity,
                        random_state=42,
                        **affinity_params
                    )
                    
                    # Fit and analyze eigenvalue spectrum
                    embedded = temp_spectral.fit_transform(data)
                    
                    # Score based on embedding quality (variance preservation)
                    embedding_variance = np.sum(np.var(embedded, axis=0))
                    
                    # Penalize if embedding has too little variance (collapsed)
                    if embedding_variance > 1e-6:
                        score = embedding_variance
                        
                        if score > best_score:
                            best_score = score
                            best_affinity = affinity
                            best_params = affinity_params.copy()
                            
                except Exception as e:
                    logger.warning(f"Spectral affinity {affinity} evaluation failed: {str(e)}")
                    continue
            
            # Adaptive eigen solver selection
            if n_samples > 1000:
                eigen_solver = 'arpack'
            else:
                eigen_solver = None  # Use default
            
            result_params = {
                'affinity': best_affinity,
                'eigen_solver': eigen_solver,
                'random_state': 42,
                'n_jobs': -1
            }
            result_params.update(best_params)
            
            return result_params
            
        except Exception as e:
            logger.warning(f"Spectral parameter optimization failed: {str(e)}")
            return {
                'affinity': 'nearest_neighbors',
                'n_neighbors': 10
            }
    
    async def _calculate_projection_quality(
        self,
        original_data: np.ndarray,
        projected_data: np.ndarray,
        config: DimensionalProjectionConfig
    ) -> Dict[str, float]:
        """Calculate quality metrics for dimensional projection"""
        
        try:
            metrics = {}
            
            # Calculate preservation of distances (stress)
            if original_data.shape[0] < 1000:  # Only for smaller datasets due to computational cost
                original_distances = pdist(original_data)
                projected_distances = pdist(projected_data)
                
                # Normalize distances
                original_distances = original_distances / np.max(original_distances)
                projected_distances = projected_distances / np.max(projected_distances)
                
                # Calculate stress (lower is better)
                stress = np.sqrt(np.sum((original_distances - projected_distances) ** 2) / np.sum(original_distances ** 2))
                metrics['stress'] = stress
            
            # Calculate explained variance ratio for linear methods
            if config.projection_method in ['pca', 'factor_analysis']:
                # Implement advanced variance analysis using eigenvalue decomposition
                covariance_matrix = np.cov(original_data.T)
                eigenvalues, eigenvectors = eigh(covariance_matrix)
                eigenvalues = np.sort(eigenvalues)[::-1]  # Sort in descending order
                
                # Calculate cumulative explained variance
                total_variance = np.sum(eigenvalues)
                explained_variance = eigenvalues[:config.target_dimensions]
                cumulative_variance_ratio = np.cumsum(explained_variance) / total_variance
                
                metrics['explained_variance_ratio'] = cumulative_variance_ratio[-1]
                metrics['individual_variance_ratios'] = (explained_variance / total_variance).tolist()
                metrics['eigenvalue_spectrum'] = eigenvalues.tolist()
                
                # Calculate effective dimensionality using participation ratio
                normalized_eigenvalues = eigenvalues / total_variance
                participation_ratio = 1.0 / np.sum(normalized_eigenvalues ** 2)
                metrics['effective_dimensionality'] = participation_ratio
            
            # Calculate silhouette score if clustering is meaningful
            if projected_data.shape[0] > 10:
                try:
                    from sklearn.cluster import KMeans
                    n_clusters = min(8, projected_data.shape[0] // 5)
                    kmeans = KMeans(n_clusters=n_clusters, random_state=42, n_init=10)
                    cluster_labels = kmeans.fit_predict(projected_data)
                    silhouette = silhouette_score(projected_data, cluster_labels)
                    metrics['silhouette_score'] = silhouette
                except:
                    metrics['silhouette_score'] = 0.0
            
            # Calculate advanced geometric and topological metrics
            
            # Intrinsic dimensionality estimation using correlation dimension
            if original_data.shape[0] > 20:
                intrinsic_dim = await self._estimate_intrinsic_dimensionality(original_data)
                metrics['intrinsic_dimensionality'] = intrinsic_dim
                metrics['dimensionality_reduction_efficiency'] = config.target_dimensions / intrinsic_dim
            
            # Local neighborhood preservation using k-ary neighborhoods
            if original_data.shape[0] < 500:  # Computational constraint
                neighborhood_preservation = await self._calculate_neighborhood_preservation(
                    original_data, projected_data, k=min(10, original_data.shape[0] // 5)
                )
                metrics['neighborhood_preservation'] = neighborhood_preservation
            
            # Manifold learning quality using geodesic distance preservation
            if config.projection_method in ['isomap', 'lle', 'spectral']:
                geodesic_preservation = await self._calculate_geodesic_preservation(
                    original_data, projected_data
                )
                metrics['geodesic_preservation'] = geodesic_preservation
            
            # Information theoretic measures
            mutual_info = await self._calculate_mutual_information_preservation(
                original_data, projected_data
            )
            metrics['mutual_information_preservation'] = mutual_info
            
            # Add computational metrics
            metrics['memory_usage'] = projected_data.nbytes / (1024 * 1024)  # MB
            metrics['computational_complexity'] = original_data.shape[0] * original_data.shape[1] * config.target_dimensions
            
            return metrics
            
        except Exception as e:
            logger.error(f"Error calculating projection quality: {str(e)}")
            return {'error': str(e)}
    
