    async def _compute_volcanic_manifold_metric(self, data: np.ndarray, volcanic_context: Dict[str, Any]) -> str:
        """Compute volcanic-aware manifold metric based on geological characteristics"""
        try:
            # Determine optimal metric based on volcanic system properties
            system_type = volcanic_context.get('system_type', 'unknown')
            eruption_style = volcanic_context.get('eruption_style', 'unknown')
            magma_composition = volcanic_context.get('magma_composition', 'unknown')
            
            # Metric selection based on volcanic characteristics
            if system_type == 'caldera' and eruption_style == 'explosive':
                return 'mahalanobis'  # Better for high-dimensional explosive systems
            elif magma_composition in ['basaltic', 'mafic']:
                return 'manhattan'    # Robust for linear volcanic processes
            elif system_type == 'stratovolcano':
                return 'minkowski'    # Flexible for complex stratovolcano dynamics
            else:
                return 'euclidean'    # Default for unknown systems
                
        except Exception as e:
            logger.warning(f"Volcanic metric computation failed: {str(e)}")
            return 'euclidean'
    
    async def _compute_projected_riemannian_metric(self, data: np.ndarray, volcanic_context: Dict[str, Any]) -> str:
        """Compute Riemannian metric for projected volcanic data"""
        try:
            # Use cosine similarity for high-dimensional projected spaces
            if data.shape[1] > 10:
                return 'cosine'
            # Use Euclidean for low-dimensional projections
            else:
                return 'euclidean'
        except:
            return 'euclidean'
    
    async def _compute_geological_significance_weight(
        self, 
        point_index: int, 
        intersection: set, 
        seismic_patterns: Dict[str, Any], 
        deformation_data: Dict[str, Any],
        geochemical_data: Dict[str, Any]
    ) -> float:
        """Compute geological significance weight for neighborhood preservation"""
        try:
            base_weight = 1.0
            
            # Seismic activity weighting
            if seismic_patterns and 'activity_levels' in seismic_patterns:
                activity_levels = seismic_patterns['activity_levels']
                if point_index < len(activity_levels):
                    seismic_weight = 1.0 + np.log(activity_levels[point_index] + 1) / 10
                    base_weight *= seismic_weight
            
            # Deformation significance weighting
            if deformation_data and 'deformation_rates' in deformation_data:
                deformation_rates = deformation_data['deformation_rates']
                if point_index < len(deformation_rates):
                    deform_weight = 1.0 + abs(deformation_rates[point_index]) / 100
                    base_weight *= deform_weight
            
            # Geochemical anomaly weighting
            if geochemical_data and 'anomaly_scores' in geochemical_data:
                anomaly_scores = geochemical_data['anomaly_scores']
                if point_index < len(anomaly_scores):
                    geochem_weight = 1.0 + anomaly_scores[point_index] / 5
                    base_weight *= geochem_weight
            
            # Neighborhood quality weighting
            if len(intersection) > 0:
                neighborhood_quality = len(intersection) / 10  # Normalize
                base_weight *= (1.0 + neighborhood_quality)
            
            return min(3.0, base_weight)  # Cap at 3x weight
            
        except Exception as e:
            logger.warning(f"Geological significance weight computation failed: {str(e)}")
            return 1.0
    
    async def _compute_temporal_volcanic_weight(
        self, 
        point_index: int, 
        volcanic_context: Dict[str, Any], 
        seismic_patterns: Dict[str, Any]
    ) -> float:
        """Compute temporal weighting based on volcanic activity patterns"""
        try:
            base_weight = 1.0
            
            # Recent activity weighting
            if 'recent_activity_index' in volcanic_context:
                recent_activity = volcanic_context['recent_activity_index']
                activity_weight = 1.0 + recent_activity / 2
                base_weight *= activity_weight
            
            # Seismic temporal patterns
            if seismic_patterns and 'temporal_patterns' in seismic_patterns:
                temporal_data = seismic_patterns['temporal_patterns']
                if point_index < len(temporal_data):
                    temporal_weight = 1.0 + temporal_data[point_index] / 5
                    base_weight *= temporal_weight
            
            return min(2.5, base_weight)  # Cap at 2.5x weight
            
        except Exception as e:
            logger.warning(f"Temporal volcanic weight computation failed: {str(e)}")
            return 1.0
    
    async def _compute_empirical_kendall_tau(self, u_data: np.ndarray, v_data: np.ndarray) -> float:
        """Compute empirical Kendall's tau for copula validation"""
        try:
            from scipy.stats import kendalltau
            
            # Ensure data is properly formatted
            u_vec = u_data.flatten() if u_data.ndim > 1 else u_data
            v_vec = v_data.flatten() if v_data.ndim > 1 else v_data
            
            if len(u_vec) != len(v_vec) or len(u_vec) < 3:
                return 0.0
            
            tau, _ = kendalltau(u_vec, v_vec)
            return tau if not np.isnan(tau) else 0.0
            
        except Exception as e:
            logger.warning(f"Empirical Kendall tau computation failed: {str(e)}")
            return 0.0
    
