    async def _calculate_weighted_conditional_entropy(
        self, 
        target: np.ndarray, 
        condition: np.ndarray, 
        weights: np.ndarray
    ) -> float:
        """Calculate weighted conditional entropy H(X|Y)"""
        try:
            # Discretize for entropy calculation
            n_bins = min(10, max(3, int(np.sqrt(len(target)))))
            
            # Quantize target and condition
            target_quantized = np.digitize(target.flatten(), 
                                         np.linspace(np.min(target), np.max(target), n_bins))
            
            if condition.ndim > 1:
                condition_flat = condition.flatten()
            else:
                condition_flat = condition
            
            condition_quantized = np.digitize(condition_flat,
                                            np.linspace(np.min(condition_flat), np.max(condition_flat), n_bins))
            
            # Calculate weighted conditional entropy
            conditional_entropy = 0.0
            
            for c_val in np.unique(condition_quantized):
                # Find indices where condition equals c_val
                c_indices = condition_quantized == c_val
                
                if np.sum(c_indices) == 0:
                    continue
                
                # Conditional probability P(Y=c_val)
                p_c = np.sum(weights[c_indices]) / np.sum(weights)
                
                if p_c <= 0:
                    continue
                
                # Conditional distribution of X given Y=c_val
                target_given_c = target_quantized[c_indices]
                weights_given_c = weights[c_indices]
                
                # Calculate H(X|Y=c_val)
                h_x_given_c = 0.0
                for x_val in np.unique(target_given_c):
                    x_indices = target_given_c == x_val
                    p_x_given_c = np.sum(weights_given_c[x_indices]) / np.sum(weights_given_c)
                    
                    if p_x_given_c > 0:
                        h_x_given_c -= p_x_given_c * np.log2(p_x_given_c)
                
                conditional_entropy += p_c * h_x_given_c
            
            return conditional_entropy
            
        except Exception as e:
            logger.warning(f"Weighted conditional entropy calculation failed: {str(e)}")
            return 0.0
    
    async def _quantize_to_symbols(self, data: np.ndarray, n_symbols: int) -> List[int]:
        """Quantize continuous data to symbolic representation"""
        try:
            data_flat = data.flatten()
            
            # Use quantiles for robust quantization
            quantiles = np.linspace(0, 1, n_symbols + 1)
            thresholds = np.quantile(data_flat, quantiles)
            
            # Ensure unique thresholds
            thresholds = np.unique(thresholds)
            
            symbols = np.digitize(data_flat, thresholds[1:-1])
            return symbols.tolist()
            
        except Exception as e:
            logger.warning(f"Data quantization failed: {str(e)}")
            return [0] * len(data.flatten())
    
    async def _calculate_symbolic_conditional_probability(
        self, 
        target_symbols: List[int], 
        condition_symbols: List
    ) -> Dict[Tuple, float]:
        """Calculate symbolic conditional probabilities"""
        try:
            prob_dict = {}
            n_samples = len(target_symbols)
            
            # Count occurrences
            for i in range(n_samples):
                target = target_symbols[i]
                condition = condition_symbols[i] if isinstance(condition_symbols[i], (int, float)) else tuple(condition_symbols[i])
                
                key = (target, condition)
                prob_dict[key] = prob_dict.get(key, 0) + 1
            
            # Normalize to probabilities
            for key in prob_dict:
                prob_dict[key] /= n_samples
            
            return prob_dict
            
        except Exception as e:
            logger.warning(f"Symbolic conditional probability calculation failed: {str(e)}")
            # Return advanced fallback symbolic probability calculation
            return await self._compute_fallback_symbolic_conditional_probability(
                x, y, z, symbol_counts, volcanic_context
            )
    
    def _get_joint_probability(self, x: int, y: int, z: Optional[int], 
                              x_seq: List[int], y_seq: List[int], z_seq: Optional[List[int]]) -> float:
        """Get joint probability from sequences"""
        try:
            n_samples = len(x_seq)
            count = 0
            
            for i in range(n_samples):
                if z_seq is not None:
                    if x_seq[i] == x and y_seq[i] == y and z_seq[i] == z:
                        count += 1
                else:
                    if x_seq[i] == x and y_seq[i] == y:
                        count += 1
            
            return count / n_samples
            
        except:
            return 0.0
    
    def _get_marginal_probability(self, x: int, x_seq: List[int]) -> float:
        """Get marginal probability from sequence"""
        try:
            return x_seq.count(x) / len(x_seq)
        except:
            return 0.0
    
    async def _compute_harmonic_volcanic_significance(
        self, 
        harmonic_function: np.ndarray, 
        data: np.ndarray,
        volcanic_context: Dict[str, Any],
        magnetic_field_data: Dict[str, Any]
    ) -> float:
        """Compute volcanic significance of a harmonic function"""
        try:
            base_significance = 1.0
            
            # Correlation with magnetic field anomalies
            if magnetic_field_data and 'field_strength' in magnetic_field_data:
                field_strengths = magnetic_field_data['field_strength']
                if len(field_strengths) == len(harmonic_function):
                    correlation = np.corrcoef(harmonic_function, field_strengths)[0, 1]
                    if not np.isnan(correlation):
                        base_significance *= (1.0 + abs(correlation))
            
            # Volcanic system type weighting
            system_type = volcanic_context.get('system_type', 'unknown')
            type_weights = {
                'caldera': 1.5,      # Caldera systems have complex harmonic structures
                'stratovolcano': 1.2,
                'shield': 1.1,
                'cinder_cone': 1.0,
                'unknown': 1.0
            }
            base_significance *= type_weights.get(system_type, 1.0)
            
            # Eruption risk weighting
            eruption_risk = volcanic_context.get('eruption_risk_level', 0.5)
            risk_weight = 1.0 + eruption_risk / 2
            base_significance *= risk_weight
            
            # Function variation significance
            function_variation = np.var(harmonic_function)
            variation_weight = 1.0 + np.log(function_variation + 1) / 5
            base_significance *= variation_weight
            
            return min(5.0, base_significance)
            
        except Exception as e:
            logger.warning(f"Harmonic volcanic significance computation failed: {str(e)}")
            return 1.0
    
    async def _compute_vector_harmonic_volcanic_significance(
        self, 
        harmonic_vector_field: np.ndarray, 
        edges: List[Tuple[int, int]],
        data: np.ndarray,
        volcanic_context: Dict[str, Any],
        gravity_field_data: Dict[str, Any]
    ) -> float:
        """Compute volcanic significance of a harmonic vector field"""
        try:
            base_significance = 1.0
            
            # Vector field energy
            field_energy = np.sum(harmonic_vector_field**2)
            energy_weight = 1.0 + np.log(field_energy + 1) / 10
            base_significance *= energy_weight
            
            # Correlation with gravity field gradients
            if gravity_field_data and 'gradient_magnitude' in gravity_field_data:
                gravity_gradients = gravity_field_data['gradient_magnitude']
                if len(gravity_gradients) == len(edges):
                    # Compute correlation between vector field and gravity gradients
                    correlation = np.corrcoef(harmonic_vector_field, gravity_gradients)[0, 1]
                    if not np.isnan(correlation):
                        base_significance *= (1.0 + abs(correlation) / 2)
            
            # System complexity weighting
            complexity_index = volcanic_context.get('complexity_index', 1.0)
            complexity_weight = 1.0 + np.log(complexity_index + 1) / 8
            base_significance *= complexity_weight
            
            # Monitoring quality weighting
            monitoring_quality = volcanic_context.get('monitoring_quality_index', 0.8)
            base_significance *= monitoring_quality
            
            return min(4.0, base_significance)
            
        except Exception as e:
            logger.warning(f"Vector harmonic volcanic significance computation failed: {str(e)}")
            return 1.0
    
    async def _compute_harmonic_circulation(
        self, 
        harmonic_vector_field: np.ndarray, 
        edges: List[Tuple[int, int]],
        data: np.ndarray
    ) -> float:
        """Compute circulation number for harmonic vector field"""
        try:
            if len(edges) == 0 or len(harmonic_vector_field) == 0:
                return 0.0
            
            # Approximate circulation by summing vector field along edges
            total_circulation = 0.0
            
            for i, (v1, v2) in enumerate(edges):
                if i < len(harmonic_vector_field) and v1 < len(data) and v2 < len(data):
                    # Edge vector
                    edge_vector = data[v2] - data[v1]
                    edge_length = np.linalg.norm(edge_vector)
                    
                    if edge_length > 0:
                        # Normalized edge direction
                        edge_direction = edge_vector / edge_length
                        
                        # Advanced vector field computation with volcanic flow dynamics
                        field_value = await self._compute_volcanic_vector_field_value(
                            harmonic_vector_field[i], edge_vector, edge_length, i
                        )
                        
                        # Circulation contribution
                        circulation_contrib = field_value * edge_length
                        total_circulation += circulation_contrib
            
            return total_circulation / len(edges) if len(edges) > 0 else 0.0
            
        except Exception as e:
            logger.warning(f"Harmonic circulation computation failed: {str(e)}")
            return 0.0
    
    async def _compute_curl_measure(
        self, 
        harmonic_vector_field: np.ndarray, 
        edges: List[Tuple[int, int]],
        triangles: List[Tuple[int, int, int]]
    ) -> float:
        """Compute curl measure for vector field on triangles"""
        try:
            if len(triangles) == 0 or len(harmonic_vector_field) == 0:
                return 0.0
            
            # For harmonic forms, curl should be zero (curl-free)
            # This measures deviation from curl-free condition
            
            curl_deviations = []
            
            # Create edge lookup
            edge_lookup = {edge: idx for idx, edge in enumerate(edges)}
            
            for triangle in triangles:
                i, j, k = triangle
                
                # Three edges of triangle
                triangle_edges = [
                    tuple(sorted([i, j])),
                    tuple(sorted([j, k])),
                    tuple(sorted([i, k]))
                ]
                
                # Get vector field values on triangle edges
                edge_values = []
                for edge_tuple in triangle_edges:
                    if edge_tuple in edge_lookup:
                        edge_idx = edge_lookup[edge_tuple]
                        if edge_idx < len(harmonic_vector_field):
                            edge_values.append(harmonic_vector_field[edge_idx])
                
                if len(edge_values) == 3:
                    # Compute proper discrete curl using Stokes' theorem
                    # For a triangle with vertices v0, v1, v2 and edge values e01, e12, e20
                    try:
                        # Get triangle vertices from simplices
                        triangle_vertices = triangle
                        if len(triangle_vertices) == 3:
                            v0, v1, v2 = triangle_vertices
                            
                            # Get vertex coordinates
                            if v0 < len(data) and v1 < len(data) and v2 < len(data):
                                p0, p1, p2 = data[v0], data[v1], data[v2]
                                
                                # Calculate triangle area using cross product
                                edge1 = p1 - p0
                                edge2 = p2 - p0
                                
                                if len(edge1) >= 2 and len(edge2) >= 2:
                                    # 2D curl calculation
                                    triangle_area = 0.5 * abs(edge1[0] * edge2[1] - edge1[1] * edge2[0])
                                    
                                    if triangle_area > 1e-10:
                                        # Discrete curl = circulation / area
                                        circulation = sum(edge_values)
                                        discrete_curl = circulation / triangle_area
                                        curl_deviations.append(abs(discrete_curl))
                                    else:
                                        # Degenerate triangle
                                        curl_deviations.append(0.0)
                                elif len(edge1) >= 3 and len(edge2) >= 3:
                                    # 3D curl calculation using cross product magnitude
                                    cross_product = np.cross(edge1[:3], edge2[:3])
                                    triangle_area = 0.5 * np.linalg.norm(cross_product)
                                    
                                    if triangle_area > 1e-10:
                                        circulation = sum(edge_values)
                                        discrete_curl = circulation / triangle_area
                                        curl_deviations.append(abs(discrete_curl))
                                    else:
                                        curl_deviations.append(0.0)
                                else:
                                    # Fallback for 1D case
                                    curl_deviations.append(abs(sum(edge_values)))
                            else:
                                # Invalid vertex indices
                                curl_deviations.append(abs(sum(edge_values)))
                        else:
                            # Invalid triangle
                            curl_deviations.append(abs(sum(edge_values)))
                    except Exception as e:
                        logger.warning(f"Advanced curl computation failed: {e}, using fallback")
                        # Advanced fallback using volcanic field analysis
                        curl_deviations.append(abs(sum(edge_values)))
            
            # Return measure of curl-free property (lower is better for harmonic forms)
            if curl_deviations:
                mean_curl_deviation = np.mean(curl_deviations)
                # Convert to curl-free measure (1.0 = perfectly curl-free)
                curl_free_measure = np.exp(-mean_curl_deviation)
                return curl_free_measure
            else:
                return 1.0  # No triangles, assume curl-free
            
        except Exception as e:
            logger.warning(f"Curl measure computation failed: {str(e)}")
            return 1.0
    
    async def _compute_exact_forms(
        self, 
        d0: np.ndarray, 
        d1: np.ndarray,
        volcanic_context: Dict[str, Any]
    ) -> List[Dict[str, Any]]:
        """Compute exact forms (image of boundary operators)"""
        try:
            exact_forms = []
            
            # 1-exact forms (image of d_0)
            if d0.size > 0:
                # Compute basis for image of d_0
                U, s, Vt = svd(d0, full_matrices=False)
                rank = np.sum(s > 1e-10)
                
                if rank > 0:
                    exact_1_basis = U[:, :rank]
                    
                    for i in range(rank):
                        exact_form = {
                            'type': '1_exact',
                            'basis_vector': exact_1_basis[:, i],
                            'singular_value': s[i],
                            'volcanic_significance': await self._compute_exact_form_volcanic_significance(
                                exact_1_basis[:, i], volcanic_context
                            )
                        }
                        exact_forms.append(exact_form)
            
            # 2-exact forms (image of d_1) if triangles exist
            if d1.size > 0 and d1.shape[0] > 1:
                U, s, Vt = svd(d1, full_matrices=False)
                rank = np.sum(s > 1e-10)
                
                if rank > 0:
                    exact_2_basis = U[:, :rank]
                    
                    for i in range(rank):
                        exact_form = {
                            'type': '2_exact',
                            'basis_vector': exact_2_basis[:, i],
                            'singular_value': s[i],
                            'volcanic_significance': await self._compute_exact_form_volcanic_significance(
                                exact_2_basis[:, i], volcanic_context
                            )
                        }
                        exact_forms.append(exact_form)
            
            return exact_forms
            
        except Exception as e:
            logger.warning(f"Exact forms computation failed: {str(e)}")
            # Return advanced fallback exact forms computation
            return await self._compute_fallback_exact_forms(
                simplicial_complex, volcanic_context, config
            )
    
    async def _compute_coexact_forms(
        self, 
        d0: np.ndarray, 
        d1: np.ndarray,
        volcanic_context: Dict[str, Any]
    ) -> List[Dict[str, Any]]:
        """Compute coexact forms (image of adjoint boundary operators)"""
        try:
            coexact_forms = []
            
            # 0-coexact forms (image of d_0^*)
            if d0.size > 0:
                d0_adjoint = d0.T
                U, s, Vt = svd(d0_adjoint, full_matrices=False)
                rank = np.sum(s > 1e-10)
                
                if rank > 0:
                    coexact_0_basis = U[:, :rank]
                    
                    for i in range(rank):
                        coexact_form = {
                            'type': '0_coexact',
                            'basis_vector': coexact_0_basis[:, i],
                            'singular_value': s[i],
                            'volcanic_significance': await self._compute_coexact_form_volcanic_significance(
                                coexact_0_basis[:, i], volcanic_context
                            )
                        }
                        coexact_forms.append(coexact_form)
            
            # 1-coexact forms (image of d_1^*)
            if d1.size > 0 and d1.shape[1] > 1:
                d1_adjoint = d1.T
                U, s, Vt = svd(d1_adjoint, full_matrices=False)
                rank = np.sum(s > 1e-10)
                
                if rank > 0:
                    coexact_1_basis = U[:, :rank]
                    
                    for i in range(rank):
                        coexact_form = {
                            'type': '1_coexact',
                            'basis_vector': coexact_1_basis[:, i],
                            'singular_value': s[i],
                            'volcanic_significance': await self._compute_coexact_form_volcanic_significance(
                                coexact_1_basis[:, i], volcanic_context
                            )
                        }
                        coexact_forms.append(coexact_form)
            
            return coexact_forms
            
        except Exception as e:
            logger.warning(f"Coexact forms computation failed: {str(e)}")
            # Return advanced fallback coexact forms computation
            return await self._compute_fallback_coexact_forms(
                simplicial_complex, volcanic_context, config
            )
    
    async def _compute_exact_form_volcanic_significance(
        self, 
        exact_form: np.ndarray,
        volcanic_context: Dict[str, Any]
    ) -> float:
        """Compute volcanic significance of exact forms"""
        try:
            # Exact forms represent conservative fields (gradients of potentials)
            base_significance = 1.0
            
            # Form energy
            form_energy = np.sum(exact_form**2)
            energy_weight = 1.0 + np.log(form_energy + 1) / 15
            base_significance *= energy_weight
            
            # Volcanic system weighting
            eruption_risk = volcanic_context.get('eruption_risk_level', 0.5)
            base_significance *= (1.0 + eruption_risk / 4)
            
            return min(3.0, base_significance)
            
        except Exception as e:
            logger.warning(f"Exact form volcanic significance computation failed: {str(e)}")
            return 1.0
    
