    async def _compute_steenrod_correction(
        self, 
        gen1: Dict[str, Any], 
        gen2: Dict[str, Any],
        cup_product_value: float,
        volcanic_context: Dict[str, Any]
    ) -> float:
        """Compute Steenrod operation correction factor"""
        try:
            # Apply correction to make cup product Steenrod-compatible
            deg1, deg2 = gen1.get('degree', 0), gen2.get('degree', 0)
            
            # Base Steenrod correction
            if abs(cup_product_value) > 100:
                # Scale down large values
                correction = 1.0 / (1.0 + np.log(abs(cup_product_value) / 100))
            else:
                correction = 1.0
            
            # Degree-dependent correction
            degree_correction = 1.0 / (1.0 + 0.1 * (deg1 + deg2))
            
            return correction * degree_correction
            
        except Exception as e:
            logger.warning(f"Steenrod correction computation failed: {str(e)}")
            return 1.0
    
