    async def _compute_ez_shuffle_products(
        self, 
        p: int, 
        q: int,
        volcanic_context: Dict[str, Any]
    ) -> float:
        """Compute Eilenberg-Zilber shuffle products"""
        try:
            # Compute (p,q)-shuffles for Eilenberg-Zilber map
            from math import factorial, comb
            
            total_degree = p + q
            
            if total_degree == 0:
                return 1.0
            
            # Number of (p,q)-shuffles
            try:
                num_shuffles = comb(total_degree, p)
            except (ValueError, OverflowError):
                num_shuffles = 1
            
            # Shuffle sum with volcanic weighting
            system_complexity = volcanic_context.get('complexity_index', 1.0)
            complexity_factor = 1.0 + np.log(system_complexity + 1) / 15
            
            shuffle_sum = num_shuffles * complexity_factor
            
            return shuffle_sum
            
        except Exception as e:
            logger.warning(f"EZ shuffle products computation failed: {str(e)}")
            return 1.0
    
