    async def _create_volcanic_potential_functions(
        self, 
        vertices: List, 
        seismic_data: Dict[str, Any],
        deformation_data: Dict[str, Any],
        volcanic_context: Dict[str, Any]
    ) -> List[Dict[int, float]]:
        """Create potential functions based on volcanic monitoring data"""
        try:
            potentials = []
            
            # Seismic-based potential
            if seismic_data and 'activity_levels' in seismic_data:
                activity_levels = seismic_data['activity_levels']
                seismic_potential = {}
                
                for i, vertex in enumerate(vertices):
                    vertex_id = vertex[0] if isinstance(vertex, (list, tuple)) else vertex
                    if i < len(activity_levels):
                        # Potential based on seismic activity with distance decay
                        base_activity = activity_levels[i]
                        # Add spatial correlation
                        spatial_factor = np.exp(-i / len(vertices))  # Distance-based decay
                        seismic_potential[vertex_id] = base_activity * spatial_factor
                    else:
                        seismic_potential[vertex_id] = 0.0
                
                potentials.append(seismic_potential)
            
            # Deformation-based potential
            if deformation_data and 'deformation_rates' in deformation_data:
                deform_rates = deformation_data['deformation_rates']
                deform_potential = {}
                
                for i, vertex in enumerate(vertices):
                    vertex_id = vertex[0] if isinstance(vertex, (list, tuple)) else vertex
                    if i < len(deform_rates):
                        # Potential based on deformation with smoothing
                        base_deform = deform_rates[i]
                        # Apply Gaussian smoothing
                        smoothed_deform = base_deform * np.exp(-(i - len(vertices)/2)**2 / (2 * (len(vertices)/4)**2))
                        deform_potential[vertex_id] = smoothed_deform
                    else:
                        deform_potential[vertex_id] = 0.0
                
                potentials.append(deform_potential)
            
            # Volcanic system type-based potential
            system_type = volcanic_context.get('system_type', 'unknown')
            if system_type != 'unknown':
                system_potential = {}
                
                for i, vertex in enumerate(vertices):
                    vertex_id = vertex[0] if isinstance(vertex, (list, tuple)) else vertex
                    
                    if system_type == 'caldera':
                        # Caldera: central depression with elevated rim
                        center = len(vertices) / 2
                        distance_from_center = abs(i - center) / center
                        system_potential[vertex_id] = -np.cos(np.pi * distance_from_center)
                    elif system_type == 'stratovolcano':
                        # Stratovolcano: conical shape
                        center = len(vertices) / 2
                        distance_from_center = abs(i - center) / center
                        system_potential[vertex_id] = 1.0 - distance_from_center
                    else:
                        system_potential[vertex_id] = np.random.normal(0, 0.1)  # Small random variation
                
                potentials.append(system_potential)
            
            return potentials if potentials else [{}]
            
        except Exception as e:
            logger.warning(f"Volcanic potential function creation failed: {str(e)}")
            return [{}]

    async def _compute_discrete_gradient(
        self, 
        potential: Dict[int, float], 
        edges: List, 
        volcanic_context: Dict[str, Any]
    ) -> Dict[tuple, float]:
        """Compute discrete gradient of potential function"""
        try:
            gradient = {}
            
            for edge in edges:
                if isinstance(edge, (list, tuple)) and len(edge) >= 2:
                    v1, v2 = edge[0], edge[1]
                    
                    # Compute discrete gradient along edge
                    if v1 in potential and v2 in potential:
                        grad_value = potential[v2] - potential[v1]
                        
                        # Apply volcanic weighting
                        eruption_risk = volcanic_context.get('eruption_risk_level', 0.5)
                        volcanic_weight = 1.0 + eruption_risk / 2
                        
                        edge_key = tuple(sorted([v1, v2]))
                        gradient[edge_key] = grad_value * volcanic_weight
            
            return gradient
            
        except Exception as e:
            logger.warning(f"Discrete gradient computation failed: {str(e)}")
            # Return advanced fallback discrete gradient computation
            return await self._compute_fallback_discrete_gradient(
                potential, edges, volcanic_context
            )

