    async def _generate_generic_volcanic_dimension_label(self, dimension_index: int, analysis: Dict[str, Any]) -> str:
        """Generate generic volcanic dimension label"""
        try:
            dominant_processes = analysis.get('dominant_processes', [])
            significance = analysis.get('significance_score', 0.5)
            
            if significance > 0.8:
                prefix = 'Primary_Volcanic'
            elif significance > 0.6:
                prefix = 'Secondary_Volcanic'
            elif significance > 0.4:
                prefix = 'Tertiary_Volcanic'
            else:
                prefix = 'Higher_Order_Volcanic'
            
            if dominant_processes:
                main_process = dominant_processes[0].replace('_', '_').title()
                return f'{prefix}_{main_process}_Component_{dimension_index + 1}'
            else:
                return f'{prefix}_Variation_Component_{dimension_index + 1}'
                
        except Exception as e:
            logger.warning(f"Generic dimension label generation failed: {str(e)}")
            return f'Volcanic_Dimension_{dimension_index + 1}'

    async def _compute_fallback_discrete_gradient(
        self, 
        potential: Dict[int, float], 
        edges: List, 
        volcanic_context: Dict[str, Any]
    ) -> Dict[tuple, float]:
        """Compute discrete gradient using advanced fallback methods with volcanic enhancement"""
        try:
            gradient = {}
            
            if not potential or not edges:
                return gradient
            
            # Get additional volcanic data for enhanced gradient computation
            magnetic_data = await self.data_connector.get_magnetic_field_data()
            flow_data = await self.data_connector.get_volcanic_flow_data()
            
            # Method 1: Standard discrete gradient with volcanic weighting
            for edge in edges:
                if isinstance(edge, (list, tuple)) and len(edge) >= 2:
                    v1, v2 = edge[0], edge[1]
                    
                    # Compute discrete gradient along edge
                    if v1 in potential and v2 in potential:
                        # Advanced discrete gradient with volcanic field corrections
                        grad_value = potential[v2] - potential[v1]
                        
                        # Apply volcanic system corrections
                        volcanic_correction = await self._compute_gradient_volcanic_correction(
                            v1, v2, grad_value, volcanic_context, magnetic_data
                        )
                        
                        # Apply flow field corrections
                        flow_correction = await self._compute_gradient_flow_correction(
                            v1, v2, grad_value, flow_data, volcanic_context
                        )
                        
                        # Combined correction
                        corrected_grad = grad_value * volcanic_correction * flow_correction
                        
                        edge_key = tuple(sorted([v1, v2]))
                        gradient[edge_key] = corrected_grad
            
            # Method 2: Smooth gradient interpolation for missing edges
            if len(gradient) < len(edges) * 0.8:  # If many edges missing gradients
                interpolated_gradients = await self._interpolate_missing_gradients(
                    potential, edges, gradient, volcanic_context
                )
                gradient.update(interpolated_gradients)
            
            # Method 3: Gradient field regularization
            regularized_gradient = await self._regularize_gradient_field(
                gradient, volcanic_context
            )
            
            # Method 4: Volcanic-specific gradient enhancements
            enhanced_gradient = await self._enhance_gradient_with_volcanic_physics(
                regularized_gradient, volcanic_context, magnetic_data, flow_data
            )
            
            return enhanced_gradient
            
        except Exception as e:
            logger.error(f"Fallback discrete gradient computation failed: {str(e)}")
            # Minimal fallback
            return {tuple(sorted([edge[0], edge[1]])): 0.0 for edge in edges 
                   if isinstance(edge, (list, tuple)) and len(edge) >= 2}

    async def _compute_gradient_volcanic_correction(
        self, 
        v1: int, 
        v2: int, 
        grad_value: float,
        volcanic_context: Dict[str, Any],
        magnetic_data: Dict[str, Any]
    ) -> float:
        """Compute volcanic correction factor for gradient"""
        try:
            correction = 1.0
            
            # System type correction
            system_type = volcanic_context.get('system_type', 'unknown') if volcanic_context else 'unknown'
            
            if system_type == 'caldera':
                # Calderas have complex gradient fields
                correction *= 1.2
            elif system_type == 'stratovolcano':
                # Stratovolcanoes have directed gradients
                correction *= 1.1
            
            # Eruption risk correction
            if volcanic_context:
                eruption_risk = volcanic_context.get('eruption_risk_level', 0.5)
                risk_correction = 1.0 + 0.3 * eruption_risk
                correction *= risk_correction
            
            # Magnetic field correction
            if magnetic_data and 'field_strength' in magnetic_data:
                field_strengths = magnetic_data['field_strength']
                if v1 < len(field_strengths) and v2 < len(field_strengths):
                    avg_field = (field_strengths[v1] + field_strengths[v2]) / 2
                    magnetic_correction = 1.0 + 0.2 * np.tanh(avg_field / 100)
                    correction *= magnetic_correction
            
            # Gradient magnitude correction
            if abs(grad_value) > 1.0:
                magnitude_correction = 1.0 + 0.1 * np.log(abs(grad_value) + 1)
                correction *= magnitude_correction
            
            return min(3.0, correction)
            
        except Exception as e:
            logger.warning(f"Gradient volcanic correction computation failed: {str(e)}")
            return 1.0

    async def _compute_gradient_flow_correction(
        self, 
        v1: int, 
        v2: int, 
        grad_value: float,
        flow_data: Dict[str, Any],
        volcanic_context: Dict[str, Any]
    ) -> float:
        """Compute flow field correction for gradient"""
        try:
            correction = 1.0
            
            if not flow_data or 'flow_vectors' not in flow_data:
                return correction
            
            flow_vectors = flow_data['flow_vectors']
            
            if v1 < len(flow_vectors) and v2 < len(flow_vectors):
                flow1 = np.array(flow_vectors[v1]) if isinstance(flow_vectors[v1], list) else np.array([flow_vectors[v1]])
                flow2 = np.array(flow_vectors[v2]) if isinstance(flow_vectors[v2], list) else np.array([flow_vectors[v2]])
                
                # Compute flow alignment with gradient direction
                if len(flow1) > 0 and len(flow2) > 0:
                    avg_flow = (flow1 + flow2) / 2
                    flow_magnitude = np.linalg.norm(avg_flow)
                    
                    if flow_magnitude > 0:
                        # Flow enhances gradient in aligned directions
                        flow_enhancement = 1.0 + 0.4 * np.tanh(flow_magnitude / 10)
                        correction *= flow_enhancement
            
            return min(2.0, correction)
            
        except Exception as e:
            logger.warning(f"Gradient flow correction computation failed: {str(e)}")
            return 1.0

    async def _interpolate_missing_gradients(
        self, 
        potential: Dict[int, float], 
        edges: List,
        existing_gradient: Dict[tuple, float],
        volcanic_context: Dict[str, Any]
    ) -> Dict[tuple, float]:
        """Interpolate gradients for edges missing from computation"""
        try:
            interpolated = {}
            
            # Find edges without gradients
            missing_edges = []
            for edge in edges:
                if isinstance(edge, (list, tuple)) and len(edge) >= 2:
                    edge_key = tuple(sorted([edge[0], edge[1]]))
                    if edge_key not in existing_gradient:
                        missing_edges.append(edge)
            
            # Interpolate using nearby gradients
            for edge in missing_edges:
                v1, v2 = edge[0], edge[1]
                edge_key = tuple(sorted([v1, v2]))
                
                # Find nearby edges with known gradients
                nearby_gradients = []
                for existing_edge, grad_val in existing_gradient.items():
                    if v1 in existing_edge or v2 in existing_edge:
                        nearby_gradients.append(grad_val)
                
                if nearby_gradients:
                    # Weighted average of nearby gradients
                    interpolated_value = np.mean(nearby_gradients)
                    
                    # Apply volcanic smoothing
                    system_type = volcanic_context.get('system_type', 'unknown') if volcanic_context else 'unknown'
                    if system_type == 'caldera':
                        smoothing_factor = 0.8  # More smoothing for calderas
                    else:
                        smoothing_factor = 0.9
                    
                    interpolated[edge_key] = interpolated_value * smoothing_factor
                else:
                    # Use potential difference if available
                    if v1 in potential and v2 in potential:
                        interpolated[edge_key] = (potential[v2] - potential[v1]) * 0.5
                    else:
                        interpolated[edge_key] = 0.0
            
            return interpolated
            
        except Exception as e:
            logger.warning(f"Gradient interpolation failed: {str(e)}")
            return {}

    async def _regularize_gradient_field(
        self, 
        gradient: Dict[tuple, float],
        volcanic_context: Dict[str, Any]
    ) -> Dict[tuple, float]:
        """Regularize gradient field for smoothness and physical consistency"""
        try:
            if not gradient:
                return gradient
            
            regularized = gradient.copy()
            
            # Compute gradient statistics
            grad_values = list(gradient.values())
            if not grad_values:
                return regularized
            
            mean_grad = np.mean(grad_values)
            std_grad = np.std(grad_values)
            
            # Remove extreme outliers
            outlier_threshold = mean_grad + 3 * std_grad
            
            for edge_key, grad_val in gradient.items():
                if abs(grad_val) > outlier_threshold:
                    # Clamp extreme values
                    sign = np.sign(grad_val)
                    regularized[edge_key] = sign * outlier_threshold * 0.8
            
            # Apply volcanic system-specific regularization
            if volcanic_context:
                system_type = volcanic_context.get('system_type', 'unknown')
                
                if system_type == 'caldera':
                    # Calderas: enforce radial gradient patterns
                    regularized = await self._apply_radial_regularization(regularized)
                elif system_type == 'stratovolcano':
                    # Stratovolcanoes: enforce vertical gradient patterns
                    regularized = await self._apply_vertical_regularization(regularized)
            
            return regularized
            
        except Exception as e:
            logger.warning(f"Gradient field regularization failed: {str(e)}")
            return gradient

    async def _enhance_gradient_with_volcanic_physics(
        self, 
        gradient: Dict[tuple, float],
        volcanic_context: Dict[str, Any],
        magnetic_data: Dict[str, Any],
        flow_data: Dict[str, Any]
    ) -> Dict[tuple, float]:
        """Enhance gradient field with volcanic physics principles"""
        try:
            enhanced = gradient.copy()
            
            if not gradient:
                return enhanced
            
            # Apply conservation principles
            enhanced = await self._apply_gradient_conservation(enhanced, volcanic_context)
            
            # Apply thermodynamic constraints
            enhanced = await self._apply_thermodynamic_gradient_constraints(
                enhanced, volcanic_context
            )
            
            # Apply electromagnetic effects
            if magnetic_data:
                enhanced = await self._apply_electromagnetic_gradient_effects(
                    enhanced, magnetic_data, volcanic_context
                )
            
            # Apply fluid dynamics effects
            if flow_data:
                enhanced = await self._apply_fluid_dynamics_gradient_effects(
                    enhanced, flow_data, volcanic_context
                )
            
            return enhanced
            
        except Exception as e:
            logger.warning(f"Volcanic physics gradient enhancement failed: {str(e)}")
            return gradient

    async def _construct_fallback_incidence_matrices(
        self, 
        simplices: Dict[int, List], 
        volcanic_context: Dict[str, Any],
        config: Dict[str, Any]
    ) -> Dict[str, Any]:
        """Construct incidence matrices using advanced fallback methods with volcanic integration"""
        try:
            incidence_data = {
                'matrices': {},
                'volcanic_weights': {},
                'topological_properties': {},
                'construction_metadata': {}
            }
            
            if not simplices:
                return incidence_data
            
            # Get volcanic data for enhanced construction
            seismic_data = await self.data_connector.get_seismic_pattern_data()
            deformation_data = await self.data_connector.get_deformation_monitoring_data()
            
            # Construct incidence matrices for each dimension pair
            max_dim = max(simplices.keys()) if simplices else 0
            
            for dim in range(max_dim):
                if dim in simplices and (dim + 1) in simplices:
                    matrix_key = f'incidence_{dim}_{dim+1}'
                    
                    # Construct incidence matrix
                    incidence_matrix = await self._construct_dimensional_incidence_matrix(
                        simplices[dim], simplices[dim + 1], dim, volcanic_context
                    )
                    
                    if incidence_matrix is not None:
                        incidence_data['matrices'][matrix_key] = incidence_matrix
                        
                        # Compute volcanic weights for this matrix
                        volcanic_weights = await self._compute_incidence_volcanic_weights(
                            incidence_matrix, dim, seismic_data, deformation_data, volcanic_context
                        )
                        incidence_data['volcanic_weights'][matrix_key] = volcanic_weights
                        
                        # Analyze topological properties
                        topo_properties = await self._analyze_incidence_topological_properties(
                            incidence_matrix, dim, volcanic_context
                        )
                        incidence_data['topological_properties'][matrix_key] = topo_properties
            
            # Add construction metadata
            incidence_data['construction_metadata'] = {
                'construction_method': 'advanced_fallback_volcanic',
                'dimensions_processed': list(range(max_dim)),
                'total_matrices': len(incidence_data['matrices']),
                'volcanic_system_type': volcanic_context.get('system_type', 'unknown') if volcanic_context else 'unknown',
                'construction_timestamp': datetime.now().isoformat()
            }
            
            # Verify incidence matrix properties
            verification_results = await self._verify_incidence_matrix_properties(
                incidence_data['matrices'], volcanic_context
            )
            incidence_data['verification_results'] = verification_results
            
            return incidence_data
            
        except Exception as e:
            logger.error(f"Fallback incidence matrix construction failed: {str(e)}")
            return {
                'matrices': {},
                'error': str(e),
                'fallback_type': 'minimal_incidence_construction'
            }

    async def _construct_dimensional_incidence_matrix(
        self, 
        lower_simplices: List, 
        higher_simplices: List,
        dimension: int,
        volcanic_context: Dict[str, Any]
    ) -> Optional[np.ndarray]:
        """Construct incidence matrix between simplices of consecutive dimensions"""
        try:
            n_lower = len(lower_simplices)
            n_higher = len(higher_simplices)
            
            if n_lower == 0 or n_higher == 0:
                # Generate synthetic incidence matrix for degenerate cases
                return await self._generate_synthetic_incidence_matrix(
                    dimension, dimension + 1, volcanic_context
                )
            
            # Initialize incidence matrix
            incidence_matrix = np.zeros((n_lower, n_higher))
            
            # Fill incidence matrix
            for j, higher_simplex in enumerate(higher_simplices):
                if isinstance(higher_simplex, (list, tuple)):
                    # Find which lower-dimensional simplices are faces of this higher simplex
                    for i, lower_simplex in enumerate(lower_simplices):
                        if isinstance(lower_simplex, (list, tuple)):
                            # Check if lower_simplex is a face of higher_simplex
                            if self._is_face_of_simplex(lower_simplex, higher_simplex):
                                # Compute orientation with volcanic weighting
                                orientation = await self._compute_volcanic_orientation(
                                    lower_simplex, higher_simplex, dimension, volcanic_context
                                )
                                incidence_matrix[i, j] = orientation
            
            return incidence_matrix
            
        except Exception as e:
            logger.warning(f"Dimensional incidence matrix construction failed: {str(e)}")
            # Return advanced fallback incidence matrix
            return await self._generate_fallback_incidence_matrix(
                dimension, volcanic_context, str(e)
            )

    def _is_face_of_simplex(self, face: List, simplex: List) -> bool:
        """Check if face is a face of simplex"""
        try:
            # Convert to sets for subset checking
            face_set = set(face) if isinstance(face, (list, tuple)) else {face}
            simplex_set = set(simplex) if isinstance(simplex, (list, tuple)) else {simplex}
            
            # Face is a subset of simplex and has one fewer vertex
            return (face_set.issubset(simplex_set) and 
                   len(face_set) == len(simplex_set) - 1)
            
        except Exception as e:
            logger.warning(f"Face checking failed: {str(e)}")
            return False

    async def _compute_volcanic_orientation(
        self, 
        face: List, 
        simplex: List,
        dimension: int,
        volcanic_context: Dict[str, Any]
    ) -> float:
        """Compute orientation with volcanic system corrections"""
        try:
            # Standard orientation computation
            base_orientation = self._compute_standard_orientation(face, simplex)
            
            # Apply volcanic corrections
            if volcanic_context:
                system_type = volcanic_context.get('system_type', 'unknown')
                
                # System-specific orientation corrections
                if system_type == 'caldera':
                    # Calderas may have reversed orientations due to collapse
                    if dimension >= 1:  # For edges and higher
                        orientation_correction = -1.0 if np.random.random() > 0.7 else 1.0
                    else:
                        orientation_correction = 1.0
                elif system_type == 'stratovolcano':
                    # Stratovolcanoes have consistent upward orientations
                    orientation_correction = 1.0
                else:
                    orientation_correction = 1.0
                
                # Activity level corrections
                activity_level = volcanic_context.get('activity_level', 0.5)
                activity_correction = 1.0 + 0.1 * activity_level * np.sin(dimension * np.pi / 4)
                
                corrected_orientation = base_orientation * orientation_correction * activity_correction
            else:
                corrected_orientation = base_orientation
            
            return corrected_orientation
            
        except Exception as e:
            logger.warning(f"Volcanic orientation computation failed: {str(e)}")
            return 1.0

    def _compute_standard_orientation(self, face: List, simplex: List) -> float:
        """Compute standard topological orientation"""
        try:
            # Convert to lists if needed
            face_list = list(face) if not isinstance(face, list) else face
            simplex_list = list(simplex) if not isinstance(simplex, list) else simplex
            
            # Find the missing vertex
            face_set = set(face_list)
            simplex_set = set(simplex_list)
            missing_vertices = simplex_set - face_set
            
            if len(missing_vertices) != 1:
                return 1.0  # Default orientation
            
            missing_vertex = list(missing_vertices)[0]
            
            # Compute orientation based on position of missing vertex
            try:
                missing_position = simplex_list.index(missing_vertex)
                # Alternating orientation based on position
                orientation = (-1) ** missing_position
                return float(orientation)
            except ValueError:
                return 1.0
            
        except Exception as e:
            logger.warning(f"Standard orientation computation failed: {str(e)}")
            return 1.0

    async def _compute_incidence_volcanic_weights(
        self, 
        incidence_matrix: np.ndarray,
        dimension: int,
        seismic_data: Dict[str, Any],
        deformation_data: Dict[str, Any],
        volcanic_context: Dict[str, Any]
    ) -> Dict[str, Any]:
        """Compute volcanic significance weights for incidence matrix entries"""
        try:
            weights = {
                'entry_weights': np.ones_like(incidence_matrix),
                'row_weights': np.ones(incidence_matrix.shape[0]),
                'column_weights': np.ones(incidence_matrix.shape[1]),
                'global_weight': 1.0
            }
            
            # Seismic activity weighting
            if seismic_data and 'activity_levels' in seismic_data:
                activity_levels = seismic_data['activity_levels']
                
                # Weight rows (lower-dimensional simplices)
                for i in range(min(len(activity_levels), incidence_matrix.shape[0])):
                    activity_weight = 1.0 + activity_levels[i] / 5
                    weights['row_weights'][i] = activity_weight
                
                # Weight columns (higher-dimensional simplices)
                for j in range(min(len(activity_levels), incidence_matrix.shape[1])):
                    activity_weight = 1.0 + activity_levels[j] / 5
                    weights['column_weights'][j] = activity_weight
            
            # Deformation-based weighting
            if deformation_data and 'deformation_rates' in deformation_data:
                deform_rates = deformation_data['deformation_rates']
                
                for i in range(min(len(deform_rates), incidence_matrix.shape[0])):
                    deform_weight = 1.0 + abs(deform_rates[i]) / 10
                    weights['row_weights'][i] *= deform_weight
            
            # Dimension-specific weighting
            if dimension == 0:
                # Vertex-edge incidence
                weights['global_weight'] = 1.2
            elif dimension == 1:
                # Edge-triangle incidence
                weights['global_weight'] = 1.1
            elif dimension == 2:
                # Triangle-tetrahedron incidence
                weights['global_weight'] = 1.0
            
            # System type weighting
            if volcanic_context:
                system_type = volcanic_context.get('system_type', 'unknown')
                if system_type == 'caldera':
                    weights['global_weight'] *= 1.15
                elif system_type == 'stratovolcano':
                    weights['global_weight'] *= 1.05
            
            # Compute entry-wise weights
            for i in range(incidence_matrix.shape[0]):
                for j in range(incidence_matrix.shape[1]):
                    weights['entry_weights'][i, j] = (
                        weights['row_weights'][i] * 
                        weights['column_weights'][j] * 
                        weights['global_weight']
                    )
            
            return weights
            
        except Exception as e:
            logger.warning(f"Incidence volcanic weights computation failed: {str(e)}")
            return {
                'entry_weights': np.ones_like(incidence_matrix),
                'row_weights': np.ones(incidence_matrix.shape[0]),
                'column_weights': np.ones(incidence_matrix.shape[1]),
                'global_weight': 1.0
            }

    async def _compute_fallback_symbolic_conditional_probability(
        self, 
        x: int, 
        y: int, 
        z: Optional[int],
        symbol_counts: Dict[str, int],
        volcanic_context: Dict[str, Any]
    ) -> Dict[str, float]:
        """Compute symbolic conditional probability using advanced fallback methods with volcanic context"""
        try:
            probabilities = {
                'conditional_probability': 0.0,
                'joint_probability': 0.0,
                'marginal_probability': 0.0,
                'volcanic_weighted_probability': 0.0,
                'uncertainty_bounds': (0.0, 1.0),
                'confidence_score': 0.0
            }
            
            if not symbol_counts:
                return probabilities
            
            # Get volcanic data for enhanced probability computation
            seismic_data = await self.data_connector.get_seismic_pattern_data()
            temporal_data = await self.data_connector.get_temporal_volcanic_data()
            
            # Total symbol count
            total_count = sum(symbol_counts.values())
            if total_count == 0:
                return probabilities
            
            # Compute basic probabilities with volcanic enhancement
            if z is not None:
                # P(X=x | Y=y, Z=z)
                joint_xyz = await self._get_enhanced_joint_probability(x, y, z, symbol_counts, volcanic_context)
                marginal_yz = await self._get_enhanced_marginal_probability(y, z, symbol_counts, volcanic_context)
                
                if marginal_yz > 0:
                    conditional_prob = joint_xyz / marginal_yz
                else:
                    conditional_prob = 0.0
                
                probabilities['joint_probability'] = joint_xyz
                probabilities['marginal_probability'] = marginal_yz
            else:
                # P(X=x | Y=y)
                joint_xy = await self._get_enhanced_joint_probability(x, y, None, symbol_counts, volcanic_context)
                marginal_y = await self._get_enhanced_marginal_probability(y, None, symbol_counts, volcanic_context)
                
                if marginal_y > 0:
                    conditional_prob = joint_xy / marginal_y
                else:
                    conditional_prob = 0.0
                
                probabilities['joint_probability'] = joint_xy
                probabilities['marginal_probability'] = marginal_y
            
            probabilities['conditional_probability'] = conditional_prob
            
            # Apply volcanic weighting
            volcanic_weight = await self._compute_probability_volcanic_weight(
                x, y, z, seismic_data, volcanic_context
            )
            
            volcanic_weighted_prob = conditional_prob * volcanic_weight
            probabilities['volcanic_weighted_probability'] = min(1.0, volcanic_weighted_prob)
            
            # Compute uncertainty bounds using Bayesian methods
            uncertainty_bounds = await self._compute_probability_uncertainty_bounds(
                conditional_prob, total_count, volcanic_context
            )
            probabilities['uncertainty_bounds'] = uncertainty_bounds
            
            # Compute confidence score
            confidence = await self._compute_probability_confidence(
                conditional_prob, total_count, volcanic_weight, temporal_data
            )
            probabilities['confidence_score'] = confidence
            
            # Add temporal correlation analysis
            if temporal_data:
                temporal_correlation = await self._analyze_temporal_probability_correlation(
                    x, y, z, temporal_data, volcanic_context
                )
                probabilities['temporal_correlation'] = temporal_correlation
            
            # Store probability analysis for research
            await self._store_probability_analysis({
                'symbols': {'x': x, 'y': y, 'z': z},
                'probabilities': probabilities,
                'volcanic_context': volcanic_context.get('system_type', 'unknown') if volcanic_context else 'unknown',
                'analysis_timestamp': datetime.now()
            })
            
            return probabilities
            
        except Exception as e:
            logger.error(f"Fallback symbolic conditional probability computation failed: {str(e)}")
            return {
                'conditional_probability': 0.0,
                'error': str(e),
                'fallback_type': 'minimal_probability_computation'
            }

    async def _get_enhanced_joint_probability(
        self, 
        x: int, 
        y: int, 
        z: Optional[int],
        symbol_counts: Dict[str, int],
        volcanic_context: Dict[str, Any]
    ) -> float:
        """Get enhanced joint probability with volcanic context weighting"""
        try:
            if z is not None:
                # Three-way joint probability
                joint_key = f"{x}_{y}_{z}"
                alt_keys = [f"{x},{y},{z}", f"({x},{y},{z})", f"{x}-{y}-{z}"]
            else:
                # Two-way joint probability
                joint_key = f"{x}_{y}"
                alt_keys = [f"{x},{y}", f"({x},{y})", f"{x}-{y}"]
            
            # Try different key formats
            joint_count = 0
            for key in [joint_key] + alt_keys:
                if key in symbol_counts:
                    joint_count = symbol_counts[key]
                    break
            
            total_count = sum(symbol_counts.values())
            if total_count == 0:
                return 0.0
            
            base_probability = joint_count / total_count
            
            # Apply volcanic context enhancement
            if volcanic_context:
                system_complexity = volcanic_context.get('complexity_index', 1.0)
                complexity_factor = 1.0 + np.log(system_complexity + 1) / 20
                
                activity_level = volcanic_context.get('activity_level', 0.5)
                activity_factor = 1.0 + activity_level / 10
                
                enhanced_probability = base_probability * complexity_factor * activity_factor
            else:
                enhanced_probability = base_probability
            
            return min(1.0, enhanced_probability)
            
        except Exception as e:
            logger.warning(f"Enhanced joint probability computation failed: {str(e)}")
            return 0.0

    async def _get_enhanced_marginal_probability(
        self, 
        y: int, 
        z: Optional[int],
        symbol_counts: Dict[str, int],
        volcanic_context: Dict[str, Any]
    ) -> float:
        """Get enhanced marginal probability with volcanic context weighting"""
        try:
            # Sum over all occurrences involving y (and z if provided)
            marginal_count = 0
            total_count = sum(symbol_counts.values())
            
            for key, count in symbol_counts.items():
                # Parse key to check if it contains y (and z)
                if self._key_contains_symbols(key, y, z):
                    marginal_count += count
            
            if total_count == 0:
                return 0.0
            
            base_probability = marginal_count / total_count
            
            # Apply volcanic enhancement
            if volcanic_context:
                eruption_risk = volcanic_context.get('eruption_risk_level', 0.5)
                risk_factor = 1.0 + eruption_risk / 8
                
                enhanced_probability = base_probability * risk_factor
            else:
                enhanced_probability = base_probability
            
            return min(1.0, enhanced_probability)
            
        except Exception as e:
            logger.warning(f"Enhanced marginal probability computation failed: {str(e)}")
            return 0.0

    def _key_contains_symbols(self, key: str, y: int, z: Optional[int]) -> bool:
        """Check if key contains the specified symbols"""
        try:
            # Convert key to string and check for symbol presence
            key_str = str(key)
            y_str = str(y)
            
            # Check if y is in the key
            if y_str not in key_str:
                return False
            
            # If z is specified, check if it's also in the key
            if z is not None:
                z_str = str(z)
                if z_str not in key_str:
                    return False
            
            return True
            
        except Exception as e:
            logger.warning(f"Symbol key checking failed: {str(e)}")
            return False

    async def _compute_probability_volcanic_weight(
        self, 
        x: int, 
        y: int, 
        z: Optional[int],
        seismic_data: Dict[str, Any],
        volcanic_context: Dict[str, Any]
    ) -> float:
        """Compute volcanic weighting factor for probability"""
        try:
            weight = 1.0
            
            # Seismic activity weighting
            if seismic_data and 'activity_levels' in seismic_data:
                activity_levels = seismic_data['activity_levels']
                
                # Weight based on symbol positions in activity data
                symbol_positions = [x, y] + ([z] if z is not None else [])
                
                activity_weights = []
                for pos in symbol_positions:
                    if pos < len(activity_levels):
                        activity_weights.append(activity_levels[pos])
                
                if activity_weights:
                    avg_activity = np.mean(activity_weights)
                    activity_weight = 1.0 + avg_activity / 5
                    weight *= activity_weight
            
            # System type weighting
            if volcanic_context:
                system_type = volcanic_context.get('system_type', 'unknown')
                
                if system_type == 'caldera':
                    weight *= 1.15  # Calderas have more complex probability distributions
                elif system_type == 'stratovolcano':
                    weight *= 1.08  # Stratovolcanoes have structured patterns
                
                # Complexity weighting
                complexity = volcanic_context.get('complexity_index', 1.0)
                complexity_weight = 1.0 + np.log(complexity + 1) / 15
                weight *= complexity_weight
            
            return min(2.0, weight)
            
        except Exception as e:
            logger.warning(f"Probability volcanic weight computation failed: {str(e)}")
            return 1.0

    async def _compute_probability_uncertainty_bounds(
        self, 
        probability: float, 
        sample_size: int,
        volcanic_context: Dict[str, Any]
    ) -> Tuple[float, float]:
        """Compute uncertainty bounds for probability estimate"""
        try:
            if sample_size <= 1:
                return (0.0, 1.0)
            
            # Use Wilson score interval for better small-sample performance
            z_score = 1.96  # 95% confidence interval
            
            # Wilson score interval
            center = probability + (z_score**2) / (2 * sample_size)
            spread = z_score * np.sqrt((probability * (1 - probability) + z_score**2 / (4 * sample_size)) / sample_size)
            denominator = 1 + z_score**2 / sample_size
            
            lower_bound = max(0.0, (center - spread) / denominator)
            upper_bound = min(1.0, (center + spread) / denominator)
            
            # Apply volcanic uncertainty corrections
            if volcanic_context:
                uncertainty_factor = volcanic_context.get('uncertainty_index', 1.0)
                
                # Increase uncertainty bounds for more uncertain volcanic systems
                bound_expansion = (upper_bound - lower_bound) * (uncertainty_factor - 1.0) * 0.1
                
                lower_bound = max(0.0, lower_bound - bound_expansion)
                upper_bound = min(1.0, upper_bound + bound_expansion)
            
            return (lower_bound, upper_bound)
            
        except Exception as e:
            logger.warning(f"Probability uncertainty bounds computation failed: {str(e)}")
            return (max(0.0, probability - 0.1), min(1.0, probability + 0.1))

    async def _compute_volcanic_wasserstein_distance(
        self, 
        center_point: np.ndarray, 
        neighbor_points: np.ndarray,
        volcanic_context: Dict[str, Any]
    ) -> float:
        """Compute volcanic-aware Wasserstein distance approximation using advanced optimal transport"""
        try:
            if len(neighbor_points) < 2:
                return 0.0
            
            # Get volcanic flow data for transport cost enhancement
            flow_data = await self.data_connector.get_volcanic_flow_data()
            deformation_data = await self.data_connector.get_deformation_monitoring_data()
            
            # Create probability distributions on neighborhoods
            n_neighbors = len(neighbor_points)
            
            # Method 1: Distance-based weights with volcanic corrections
            distances_to_center = np.linalg.norm(neighbor_points - center_point, axis=1)
            
            # Apply volcanic flow corrections to distances
            if flow_data and 'flow_vectors' in flow_data:
                flow_corrected_distances = await self._apply_flow_corrections_to_distances(
                    distances_to_center, neighbor_points, center_point, flow_data
                )
            else:
                flow_corrected_distances = distances_to_center
            
            # Create probability distributions
            # Distribution 1: Uniform on neighbors
            uniform_weights = np.ones(n_neighbors) / n_neighbors
            
            # Distribution 2: Distance-weighted with volcanic corrections
            if np.sum(flow_corrected_distances) > 0:
                inv_distances = 1.0 / (flow_corrected_distances + 1e-10)
                distance_weights = inv_distances / np.sum(inv_distances)
            else:
                distance_weights = uniform_weights
            
            # Method 2: Advanced Wasserstein-1 approximation
            wasserstein_1 = await self._compute_wasserstein_1_approximation(
                uniform_weights, distance_weights, neighbor_points, volcanic_context
            )
            
            # Method 3: Volcanic transport cost matrix
            transport_costs = await self._compute_volcanic_transport_costs(
                neighbor_points, center_point, deformation_data, volcanic_context
            )
            
            # Method 4: Sinkhorn approximation for regularized optimal transport
            sinkhorn_distance = await self._compute_sinkhorn_approximation(
                uniform_weights, distance_weights, transport_costs, volcanic_context
            )
            
            # Combine methods with volcanic system weighting
            system_type = volcanic_context.get('system_type', 'unknown') if volcanic_context else 'unknown'
            
            if system_type == 'caldera':
                # Calderas: emphasize Sinkhorn method for complex transport
                combined_distance = 0.3 * wasserstein_1 + 0.7 * sinkhorn_distance
            elif system_type == 'stratovolcano':
                # Stratovolcanoes: balanced approach
                combined_distance = 0.5 * wasserstein_1 + 0.5 * sinkhorn_distance
            else:
                # Unknown systems: conservative weighting
                combined_distance = 0.6 * wasserstein_1 + 0.4 * sinkhorn_distance
            
            # Apply volcanic system corrections
            eruption_risk = volcanic_context.get('eruption_risk_level', 0.5) if volcanic_context else 0.5
            risk_correction = 1.0 + eruption_risk / 4
            
            final_distance = combined_distance * risk_correction
            
            return min(10.0, final_distance)  # Cap at reasonable maximum
            
        except Exception as e:
            logger.warning(f"Volcanic Wasserstein distance computation failed: {str(e)}")
            # Advanced fallback using volcanic-weighted distance metrics
            if len(neighbor_points) > 0:
                return np.mean(np.linalg.norm(neighbor_points - center_point, axis=1))
            return 0.0

    async def _apply_flow_corrections_to_distances(
        self, 
        distances: np.ndarray, 
        neighbor_points: np.ndarray,
        center_point: np.ndarray,
        flow_data: Dict[str, Any]
    ) -> np.ndarray:
        """Apply volcanic flow corrections to distance measurements"""
        try:
            corrected_distances = distances.copy()
            
            if 'flow_vectors' not in flow_data:
                return corrected_distances
            
            flow_vectors = flow_data['flow_vectors']
            
            for i, neighbor in enumerate(neighbor_points):
                if i < len(flow_vectors):
                    # Get flow vector at neighbor position
                    flow_vector = np.array(flow_vectors[i]) if isinstance(flow_vectors[i], list) else np.array([flow_vectors[i]])
                    
                    # Compute direction from center to neighbor
                    direction = neighbor - center_point
                    direction_norm = np.linalg.norm(direction)
                    
                    if direction_norm > 0 and len(flow_vector) >= len(direction):
                        direction_unit = direction / direction_norm
                        flow_unit = flow_vector[:len(direction)] / (np.linalg.norm(flow_vector[:len(direction)]) + 1e-10)
                        
                        # Flow alignment factor
                        alignment = np.dot(direction_unit, flow_unit)
                        
                        # Correct distance based on flow alignment
                        # Flow in same direction reduces effective distance
                        # Flow in opposite direction increases effective distance
                        flow_correction = 1.0 - 0.3 * alignment
                        corrected_distances[i] = distances[i] * flow_correction
            
            return corrected_distances
            
        except Exception as e:
            logger.warning(f"Flow corrections to distances failed: {str(e)}")
            return distances

    async def _compute_wasserstein_1_approximation(
        self, 
        weights1: np.ndarray, 
        weights2: np.ndarray,
        points: np.ndarray,
        volcanic_context: Dict[str, Any]
    ) -> float:
        """Compute Wasserstein-1 distance approximation"""
        try:
            if len(weights1) != len(weights2) or len(weights1) != len(points):
                return 0.0
            
            # Sort points by first coordinate for 1D Wasserstein computation
            if points.shape[1] > 0:
                sort_indices = np.argsort(points[:, 0])
                sorted_weights1 = weights1[sort_indices]
                sorted_weights2 = weights2[sort_indices]
                sorted_points = points[sort_indices]
                
                # Compute cumulative distributions
                cdf1 = np.cumsum(sorted_weights1)
                cdf2 = np.cumsum(sorted_weights2)
                
                # Wasserstein-1 distance as integral of CDF differences
                wasserstein_1 = 0.0
                for i in range(len(sorted_points) - 1):
                    interval_length = np.linalg.norm(sorted_points[i+1] - sorted_points[i])
                    cdf_diff = abs(cdf1[i] - cdf2[i])
                    wasserstein_1 += cdf_diff * interval_length
                
                # Apply volcanic corrections
                if volcanic_context:
                    complexity = volcanic_context.get('complexity_index', 1.0)
                    complexity_correction = 1.0 + np.log(complexity + 1) / 20
                    wasserstein_1 *= complexity_correction
                
                return wasserstein_1
            
            return 0.0
            
        except Exception as e:
            logger.warning(f"Wasserstein-1 approximation failed: {str(e)}")
            return 0.0

    async def _compute_volcanic_transport_costs(
        self, 
        points: np.ndarray, 
        center_point: np.ndarray,
        deformation_data: Dict[str, Any],
        volcanic_context: Dict[str, Any]
    ) -> np.ndarray:
        """Compute volcanic-aware transport cost matrix"""
        try:
            n_points = len(points)
            cost_matrix = np.zeros((n_points, n_points))
            
            # Base costs: Euclidean distances
            for i in range(n_points):
                for j in range(n_points):
                    base_cost = np.linalg.norm(points[i] - points[j])
                    
                    # Apply deformation corrections
                    if deformation_data and 'deformation_rates' in deformation_data:
                        deform_rates = deformation_data['deformation_rates']
                        
                        if i < len(deform_rates) and j < len(deform_rates):
                            # Higher deformation increases transport cost
                            deform_factor = 1.0 + (abs(deform_rates[i]) + abs(deform_rates[j])) / 20
                            base_cost *= deform_factor
                    
                    # Apply volcanic system corrections
                    if volcanic_context:
                        system_type = volcanic_context.get('system_type', 'unknown')
                        
                        if system_type == 'caldera':
                            # Calderas: radial transport patterns
                            center_dist_i = np.linalg.norm(points[i] - center_point)
                            center_dist_j = np.linalg.norm(points[j] - center_point)
                            
                            # Radial transport is easier
                            if abs(center_dist_i - center_dist_j) < 0.1 * np.linalg.norm(points[i] - points[j]):
                                base_cost *= 0.8  # Reduce cost for radial transport
                        
                        elif system_type == 'stratovolcano':
                            # Stratovolcanoes: vertical transport patterns
                            if len(points[i]) >= 3 and len(points[j]) >= 3:
                                # Assume last coordinate is elevation
                                elevation_diff = abs(points[i][-1] - points[j][-1])
                                horizontal_dist = np.linalg.norm(points[i][:-1] - points[j][:-1])
                                
                                # Vertical transport is more difficult
                                if elevation_diff > horizontal_dist:
                                    base_cost *= 1.3
                    
                    cost_matrix[i, j] = base_cost
            
            return cost_matrix
            
        except Exception as e:
            logger.warning(f"Volcanic transport costs computation failed: {str(e)}")
            # Fallback to Euclidean distance matrix
            n_points = len(points)
            cost_matrix = np.zeros((n_points, n_points))
            for i in range(n_points):
                for j in range(n_points):
                    cost_matrix[i, j] = np.linalg.norm(points[i] - points[j])
            return cost_matrix

    async def _compute_sinkhorn_approximation(
        self, 
        weights1: np.ndarray, 
        weights2: np.ndarray,
        cost_matrix: np.ndarray,
        volcanic_context: Dict[str, Any]
    ) -> float:
        """Compute Sinkhorn approximation for regularized optimal transport"""
        try:
            if cost_matrix.shape[0] != len(weights1) or cost_matrix.shape[1] != len(weights2):
                return 0.0
            
            # Regularization parameter
            epsilon = 0.1
            
            # Apply volcanic regularization adjustments
            if volcanic_context:
                activity_level = volcanic_context.get('activity_level', 0.5)
                # Higher activity increases regularization (more diffuse transport)
                epsilon *= (1.0 + activity_level)
            
            # Sinkhorn kernel
            K = np.exp(-cost_matrix / epsilon)
            
            # Initialize dual variables
            u = np.ones(len(weights1)) / len(weights1)
            v = np.ones(len(weights2)) / len(weights2)
            
            # Sinkhorn iterations
            max_iterations = 100
            tolerance = 1e-6
            
            for iteration in range(max_iterations):
                u_old = u.copy()
                
                # Update u
                u = weights1 / (K @ v + 1e-10)
                
                # Update v
                v = weights2 / (K.T @ u + 1e-10)
                
                # Check convergence
                if np.linalg.norm(u - u_old) < tolerance:
                    break
            
            # Compute optimal transport cost
            transport_plan = np.outer(u, v) * K
            sinkhorn_cost = np.sum(transport_plan * cost_matrix)
            
            return sinkhorn_cost
            
        except Exception as e:
            logger.warning(f"Sinkhorn approximation failed: {str(e)}")
            return np.mean(cost_matrix) if cost_matrix.size > 0 else 0.0


