    async def _store_visualization_metadata(self, visualization: MultidimensionalVisualization):
        """Store visualization metadata in database"""
        try:
            query = """
            INSERT INTO visualization_metadata 
            (visualization_id, data_source, projection_method, components, performance_metrics, created_at)
            VALUES (%s, %s, %s, %s, %s, %s)
            """
            
            await self.db_manager.execute_query(
                query,
                (
                    visualization.visualization_id,
                    visualization.data_source,
                    visualization.projection_method,
                    json.dumps(visualization.visual_encoding),
                    json.dumps(visualization.performance_metrics),
                    datetime.now()
                )
            )
            
            logger.info(f"Visualization metadata stored for {visualization.visualization_id}")
            
        except Exception as e:
            logger.error(f"Error storing visualization metadata: {str(e)}")
    
    async def _create_network_graph_3d_visualization(
        self,
        dimensional_data: HigherDimensionalData,
        patterns: List[DimensionalPattern],
        config: Dict[str, Any]
    ) -> Dict[str, Any]:
        """Create 3D network graph visualization for pattern relationships"""
        try:
            # Filter network-related patterns
            network_patterns = [p for p in patterns if 'network' in p.pattern_type or 'community' in p.pattern_type]
            
            if not network_patterns or not PLOTLY_AVAILABLE:
                return {'type': 'network_graph_3d', 'error': 'No network patterns or Plotly unavailable'}
            
            # Create network graph
            G = nx.Graph()
            
            # Add nodes for each pattern
            for i, pattern in enumerate(network_patterns):
                G.add_node(i, 
                          pattern_type=pattern.pattern_type,
                          significance=pattern.significance_score,
                          coordinates=pattern.dimensional_coordinates)
            
            # Add edges based on pattern similarity
            for i in range(len(network_patterns)):
                for j in range(i + 1, len(network_patterns)):
                    # Calculate similarity between patterns
                    similarity = await self._calculate_pattern_similarity(network_patterns[i], network_patterns[j])
                    
                    if similarity > 0.3:  # Threshold for connection
                        G.add_edge(i, j, weight=similarity)
            
            # Generate 3D layout
            pos_3d = await self._generate_3d_network_layout(G, network_patterns)
            
            # Create 3D network visualization
            fig = go.Figure()
            
            # Add edges
            edge_x, edge_y, edge_z = [], [], []
            for edge in G.edges():
                x0, y0, z0 = pos_3d[edge[0]]
                x1, y1, z1 = pos_3d[edge[1]]
                edge_x.extend([x0, x1, None])
                edge_y.extend([y0, y1, None])
                edge_z.extend([z0, z1, None])
            
            fig.add_trace(go.Scatter3d(
                x=edge_x, y=edge_y, z=edge_z,
                mode='lines',
                line=dict(color='rgba(125,125,125,0.5)', width=2),
                hoverinfo='none',
                name='Pattern Connections'
            ))
            
            # Add nodes
            node_x = [pos_3d[node][0] for node in G.nodes()]
            node_y = [pos_3d[node][1] for node in G.nodes()]
            node_z = [pos_3d[node][2] for node in G.nodes()]
            node_colors = [network_patterns[node].significance_score for node in G.nodes()]
            node_sizes = [20 + 30 * network_patterns[node].significance_score for node in G.nodes()]
            
            fig.add_trace(go.Scatter3d(
                x=node_x, y=node_y, z=node_z,
                mode='markers+text',
                marker=dict(
                    size=node_sizes,
                    color=node_colors,
                    colorscale='Viridis',
                    showscale=True,
                    colorbar=dict(title="Pattern Significance")
                ),
                text=[f"P{i}" for i in G.nodes()],
                textposition="middle center",
                hovertemplate='<b>Pattern %{text}</b><br>' +
                             'Type: %{customdata[0]}<br>' +
                             'Significance: %{customdata[1]:.3f}<extra></extra>',
                customdata=[[network_patterns[node].pattern_type, network_patterns[node].significance_score] for node in G.nodes()],
                name='Pattern Nodes'
            ))
            
            fig.update_layout(
                title='3D Network Graph: Pattern Relationships',
                scene=dict(
                    xaxis_title='Network X',
                    yaxis_title='Network Y',
                    zaxis_title='Network Z',
                    camera=dict(eye=dict(x=1.5, y=1.5, z=1.5))
                ),
                showlegend=True,
                width=1000,
                height=800
            )
            
            return {
                'type': 'network_graph_3d',
                'figure': fig,
                'metadata': {
                    'n_patterns': len(network_patterns),
                    'n_connections': G.number_of_edges(),
                    'network_density': nx.density(G)
                }
            }
            
        except Exception as e:
            logger.error(f"3D network graph visualization failed: {str(e)}")
            return {'type': 'network_graph_3d', 'error': str(e)}
    
    async def _create_temporal_evolution_visualization(
        self,
        dimensional_data: HigherDimensionalData,
        patterns: List[DimensionalPattern],
        config: Dict[str, Any]
    ) -> Dict[str, Any]:
        """Create temporal evolution visualization for time-series patterns"""
        try:
            if not PLOTLY_AVAILABLE:
                return {'type': 'temporal_evolution', 'error': 'Plotly unavailable'}
            
            # Extract temporal information from patterns
            temporal_patterns = []
            for pattern in patterns:
                if 'timestamp' in pattern.discovery_metadata:
                    temporal_patterns.append(pattern)
            
            if not temporal_patterns:
                return {'type': 'temporal_evolution', 'error': 'No temporal patterns found'}
            
            # Sort patterns by timestamp
            temporal_patterns.sort(key=lambda p: p.discovery_metadata['timestamp'])
            
            # Create temporal evolution plot
            fig = make_subplots(
                rows=2, cols=2,
                subplot_titles=('Pattern Significance Over Time', 'Pattern Type Evolution', 
                               'Dimensional Coordinates Evolution', 'Pattern Discovery Rate'),
                specs=[[{"secondary_y": True}, {"type": "bar"}],
                       [{"type": "scatter"}, {"type": "histogram"}]]
            )
            
            # 1. Pattern significance over time
            timestamps = [datetime.fromisoformat(p.discovery_metadata['timestamp'].replace('Z', '+00:00')) for p in temporal_patterns]
            significances = [p.significance_score for p in temporal_patterns]
            
            fig.add_trace(
                go.Scatter(
                    x=timestamps, y=significances,
                    mode='lines+markers',
                    name='Significance',
                    line=dict(color='blue')
                ),
                row=1, col=1
            )
            
            # Add moving average
            if len(significances) > 5:
                window_size = min(10, len(significances) // 3)
                moving_avg = np.convolve(significances, np.ones(window_size)/window_size, mode='valid')
                moving_avg_timestamps = timestamps[window_size-1:]
                
                fig.add_trace(
                    go.Scatter(
                        x=moving_avg_timestamps, y=moving_avg,
                        mode='lines',
                        name='Moving Average',
                        line=dict(color='red', dash='dash')
                    ),
                    row=1, col=1
                )
            
            # 2. Pattern type evolution
            pattern_types = [p.pattern_type for p in temporal_patterns]
            type_counts = {}
            for ptype in pattern_types:
                type_counts[ptype] = type_counts.get(ptype, 0) + 1
            
            fig.add_trace(
                go.Bar(
                    x=list(type_counts.keys()),
                    y=list(type_counts.values()),
                    name='Pattern Types',
                    marker=dict(color='viridis')
                ),
                row=1, col=2
            )
            
            # 3. Dimensional coordinates evolution
            if temporal_patterns and len(temporal_patterns[0].dimensional_coordinates) >= 2:
                x_coords = [p.dimensional_coordinates[0] for p in temporal_patterns]
                y_coords = [p.dimensional_coordinates[1] for p in temporal_patterns]
                
                fig.add_trace(
                    go.Scatter(
                        x=x_coords, y=y_coords,
                        mode='markers+lines',
                        marker=dict(
                            color=list(range(len(temporal_patterns))),
                            colorscale='Viridis',
                            size=8
                        ),
                        name='Coordinate Evolution',
                        text=[f"T{i}" for i in range(len(temporal_patterns))],
                        hovertemplate='Time: %{text}<br>X: %{x:.3f}<br>Y: %{y:.3f}<extra></extra>'
                    ),
                    row=2, col=1
                )
            
            # 4. Pattern discovery rate histogram
            # Group patterns by hour
            hourly_counts = {}
            for timestamp in timestamps:
                hour_key = timestamp.replace(minute=0, second=0, microsecond=0)
                hourly_counts[hour_key] = hourly_counts.get(hour_key, 0) + 1
            
            if hourly_counts:
                fig.add_trace(
                    go.Histogram(
                        x=list(hourly_counts.values()),
                        nbinsx=20,
                        name='Discovery Rate Distribution',
                        marker=dict(color='green', opacity=0.7)
                    ),
                    row=2, col=2
                )
            
            fig.update_layout(
                title='Temporal Evolution of Volcanic Patterns',
                height=800,
                width=1400,
                showlegend=True
            )
            
            return {
                'type': 'temporal_evolution',
                'figure': fig,
                'metadata': {
                    'n_temporal_patterns': len(temporal_patterns),
                    'time_span': (min(timestamps), max(timestamps)) if timestamps else None,
                    'pattern_types': len(type_counts)
                }
            }
            
        except Exception as e:
            logger.error(f"Temporal evolution visualization failed: {str(e)}")
            return {'type': 'temporal_evolution', 'error': str(e)}
    
    async def _create_uncertainty_visualization(
        self,
        dimensional_data: HigherDimensionalData,
        patterns: List[DimensionalPattern],
        config: Dict[str, Any]
    ) -> Dict[str, Any]:
        """Create uncertainty visualization for pattern confidence"""
        try:
            if not PLOTLY_AVAILABLE:
                return {'type': 'uncertainty_visualization', 'error': 'Plotly unavailable'}
            
            # Filter patterns with uncertainty information
            uncertain_patterns = [p for p in patterns if hasattr(p, 'uncertainty_bounds') and p.uncertainty_bounds]
            
            if not uncertain_patterns:
                return {'type': 'uncertainty_visualization', 'error': 'No uncertainty information available'}
            
            fig = make_subplots(
                rows=2, cols=2,
                subplot_titles=('Uncertainty Bounds Distribution', 'Confidence vs Significance', 
                               'Uncertainty by Pattern Type', 'Error Bars Visualization'),
                specs=[[{"type": "histogram"}, {"type": "scatter"}],
                       [{"type": "box"}, {"type": "scatter"}]]
            )
            
            # Extract uncertainty data
            lower_bounds = [p.uncertainty_bounds[0] for p in uncertain_patterns]
            upper_bounds = [p.uncertainty_bounds[1] for p in uncertain_patterns]
            uncertainty_ranges = [upper - lower for upper, lower in zip(upper_bounds, lower_bounds)]
            significances = [p.significance_score for p in uncertain_patterns]
            pattern_types = [p.pattern_type for p in uncertain_patterns]
            
            # 1. Uncertainty bounds distribution
            fig.add_trace(
                go.Histogram(
                    x=uncertainty_ranges,
                    nbinsx=20,
                    name='Uncertainty Range',
                    marker=dict(color='blue', opacity=0.7)
                ),
                row=1, col=1
            )
            
            # 2. Confidence vs Significance scatter
            confidence_scores = [1.0 - ur for ur in uncertainty_ranges]  # Higher uncertainty = lower confidence
            
            fig.add_trace(
                go.Scatter(
                    x=significances, y=confidence_scores,
                    mode='markers',
                    marker=dict(
                        size=10,
                        color=uncertainty_ranges,
                        colorscale='Reds',
                        showscale=True,
                        colorbar=dict(title="Uncertainty Range")
                    ),
                    name='Confidence vs Significance',
                    text=[f"Type: {pt}" for pt in pattern_types],
                    hovertemplate='Significance: %{x:.3f}<br>Confidence: %{y:.3f}<br>%{text}<extra></extra>'
                ),
                row=1, col=2
            )
            
            # 3. Uncertainty by pattern type (box plot)
            unique_types = list(set(pattern_types))
            for ptype in unique_types:
                type_uncertainties = [ur for ur, pt in zip(uncertainty_ranges, pattern_types) if pt == ptype]
                
                fig.add_trace(
                    go.Box(
                        y=type_uncertainties,
                        name=ptype,
                        boxpoints='all',
                        jitter=0.3,
                        pointpos=-1.8
                    ),
                    row=2, col=1
                )
            
            # 4. Error bars visualization
            if len(uncertain_patterns[0].dimensional_coordinates) >= 2:
                x_coords = [p.dimensional_coordinates[0] for p in uncertain_patterns]
                y_coords = [p.dimensional_coordinates[1] for p in uncertain_patterns]
                
                # Use uncertainty range as error bar size
                error_x = [ur * 0.1 for ur in uncertainty_ranges]  # Scale for visibility
                error_y = [ur * 0.1 for ur in uncertainty_ranges]
                
                fig.add_trace(
                    go.Scatter(
                        x=x_coords, y=y_coords,
                        mode='markers',
                        error_x=dict(type='data', array=error_x, visible=True),
                        error_y=dict(type='data', array=error_y, visible=True),
                        marker=dict(
                            size=8,
                            color=significances,
                            colorscale='Viridis'
                        ),
                        name='Patterns with Uncertainty',
                        text=[f"Uncertainty: {ur:.3f}" for ur in uncertainty_ranges],
                        hovertemplate='X: %{x:.3f}<br>Y: %{y:.3f}<br>%{text}<extra></extra>'
                    ),
                    row=2, col=2
                )
            
            fig.update_layout(
                title='Uncertainty Analysis for Volcanic Patterns',
                height=800,
                width=1400,
                showlegend=True
            )
            
            return {
                'type': 'uncertainty_visualization',
                'figure': fig,
                'metadata': {
                    'n_uncertain_patterns': len(uncertain_patterns),
                    'mean_uncertainty': np.mean(uncertainty_ranges),
                    'max_uncertainty': np.max(uncertainty_ranges),
                    'min_uncertainty': np.min(uncertainty_ranges)
                }
            }
            
        except Exception as e:
            logger.error(f"Uncertainty visualization failed: {str(e)}")
            return {'type': 'uncertainty_visualization', 'error': str(e)}
    
    async def _create_comparative_analysis_visualization(
        self,
        dimensional_data: HigherDimensionalData,
        patterns: List[DimensionalPattern],
        config: Dict[str, Any]
    ) -> Dict[str, Any]:
        """Create comparative analysis visualization for multiple datasets or methods"""
        try:
            if not PLOTLY_AVAILABLE:
                return {'type': 'comparative_analysis', 'error': 'Plotly unavailable'}
            
            # Group patterns by discovery method
            method_groups = {}
            for pattern in patterns:
                method = pattern.discovery_method
                if method not in method_groups:
                    method_groups[method] = []
                method_groups[method].append(pattern)
            
            if len(method_groups) < 2:
                return {'type': 'comparative_analysis', 'error': 'Need at least 2 methods for comparison'}
            
            fig = make_subplots(
                rows=2, cols=2,
                subplot_titles=('Method Performance Comparison', 'Pattern Distribution by Method', 
                               'Significance Score Comparison', 'Method Efficiency Analysis'),
                specs=[[{"type": "bar"}, {"type": "violin"}],
                       [{"type": "scatter"}, {"type": "radar"}]]
            )
            
            methods = list(method_groups.keys())
            
            # 1. Method performance comparison
            method_counts = [len(method_groups[method]) for method in methods]
            method_avg_significance = [np.mean([p.significance_score for p in method_groups[method]]) for method in methods]
            
            fig.add_trace(
                go.Bar(
                    x=methods,
                    y=method_counts,
                    name='Pattern Count',
                    marker=dict(color='blue', opacity=0.7),
                    yaxis='y',
                    offsetgroup=1
                ),
                row=1, col=1
            )
            
            # Add secondary y-axis for average significance
            fig.add_trace(
                go.Scatter(
                    x=methods,
                    y=method_avg_significance,
                    mode='markers+lines',
                    name='Avg Significance',
                    marker=dict(color='red', size=10),
                    yaxis='y2',
                    line=dict(color='red')
                ),
                row=1, col=1
            )
            
            # 2. Pattern distribution by method (violin plot)
            for method in methods:
                significances = [p.significance_score for p in method_groups[method]]
                
                fig.add_trace(
                    go.Violin(
                        y=significances,
                        name=method,
                        box_visible=True,
                        meanline_visible=True
                    ),
                    row=1, col=2
                )
            
            # 3. Significance score comparison (scatter)
            if len(methods) >= 2:
                method1_scores = [p.significance_score for p in method_groups[methods[0]]]
                method2_scores = [p.significance_score for p in method_groups[methods[1]]]
                
                # Match patterns by index (assuming same order)
                min_len = min(len(method1_scores), len(method2_scores))
                
                fig.add_trace(
                    go.Scatter(
                        x=method1_scores[:min_len],
                        y=method2_scores[:min_len],
                        mode='markers',
                        marker=dict(size=8, color='green', opacity=0.7),
                        name=f'{methods[0]} vs {methods[1]}',
                        text=[f"Pattern {i}" for i in range(min_len)],
                        hovertemplate=f'{methods[0]}: %{{x:.3f}}<br>{methods[1]}: %{{y:.3f}}<br>%{{text}}<extra></extra>'
                    ),
                    row=2, col=1
                )
                
                # Add diagonal line for reference
                max_score = max(max(method1_scores[:min_len]), max(method2_scores[:min_len]))
                fig.add_trace(
                    go.Scatter(
                        x=[0, max_score],
                        y=[0, max_score],
                        mode='lines',
                        line=dict(dash='dash', color='red'),
                        name='Equal Performance',
                        showlegend=False
                    ),
                    row=2, col=1
                )
            
            # 4. Method efficiency analysis (radar chart)
            # Calculate efficiency metrics for each method
            efficiency_metrics = {}
            for method in methods:
                method_patterns = method_groups[method]
                efficiency_metrics[method] = {
                    'Pattern Count': len(method_patterns),
                    'Avg Significance': np.mean([p.significance_score for p in method_patterns]),
                    'Max Significance': np.max([p.significance_score for p in method_patterns]),
                    'Consistency': 1.0 - np.std([p.significance_score for p in method_patterns]),
                    'Coverage': len(set([p.pattern_type for p in method_patterns])) / len(set([p.pattern_type for p in patterns]))
                }
            
            # Normalize metrics to 0-1 scale for radar chart
            all_values = {}
            for metric in ['Pattern Count', 'Avg Significance', 'Max Significance', 'Consistency', 'Coverage']:
                values = [efficiency_metrics[method][metric] for method in methods]
                max_val = max(values) if max(values) > 0 else 1
                all_values[metric] = [v / max_val for v in values]
            
            for i, method in enumerate(methods):
                fig.add_trace(
                    go.Scatterpolar(
                        r=[all_values[metric][i] for metric in all_values.keys()],
                        theta=list(all_values.keys()),
                        fill='toself',
                        name=method,
                        opacity=0.6
                    ),
                    row=2, col=2
                )
            
            fig.update_layout(
                title='Comparative Analysis of Pattern Discovery Methods',
                height=800,
                width=1400,
                showlegend=True
            )
            
            return {
                'type': 'comparative_analysis',
                'figure': fig,
                'metadata': {
                    'methods_compared': len(methods),
                    'total_patterns': len(patterns),
                    'best_method': max(methods, key=lambda m: np.mean([p.significance_score for p in method_groups[m]])),
                    'efficiency_metrics': efficiency_metrics
                }
            }
            
        except Exception as e:
            logger.error(f"Comparative analysis visualization failed: {str(e)}")
            return {'type': 'comparative_analysis', 'error': str(e)}
    
