        # 8. Hit problem compatibility
        hit_compatible = await self._check_hit_compatibility(value, indeterminacy_space)
        
        # 9. Kameko map compatibility
        kameko_compatible = await self._check_kameko_compatibility(value, indeterminacy_space)
        
        # 10. Singer transfer compatibility
        singer_compatible = await self._check_singer_compatibility(value, indeterminacy_space)
        
        # 11. Lannes T-functor compatibility
        lannes_compatible = await self._check_lannes_compatibility(value, indeterminacy_space)
        
        # 12. Excess formula compatibility
        excess_compatible = await self._check_excess_compatibility(value, indeterminacy_space)
        
        # 13. Unstable module compatibility
        unstable_compatible = await self._check_unstable_module_compatibility(value, indeterminacy_space)
        
        # 14. Chromatic compatibility
        chromatic_compatible = await self._check_chromatic_steenrod_compatibility(value, indeterminacy_space)
        
        compatibility_checks = [
            instability_compatible,
            adem_compatible,
            cartan_compatible,
            wu_compatible,
            milnor_compatible,
            lambda_compatible,
            margolis_compatible,
            hit_compatible,
            kameko_compatible,
            singer_compatible,
            lannes_compatible,
            excess_compatible,
            unstable_compatible,
            chromatic_compatible
        ]
        
        # Weight by theoretical importance
        weights = np.array([0.12, 0.1, 0.09, 0.08, 0.1, 0.07, 0.06, 0.07, 0.05, 0.05, 0.06, 0.05, 0.08, 0.07])
        compatibility_score = np.dot(compatibility_checks, weights)
        
        # Field-specific compatibility
        if coefficient_field == 'F_2':
            # Characteristic 2 specific checks
            sq1_compatible = await self._check_sq1_compatibility(value, indeterminacy_space)
            if sq1_compatible:
                compatibility_score += 0.1
        
        elif coefficient_field.startswith('F_'):
            # Odd prime characteristic
            try:
                p = int(coefficient_field.split('_')[1])
                if p > 2:
                    bockstein_compatible = await self._check_bockstein_compatibility(value, indeterminacy_space, p)
                    if bockstein_compatible:
                        compatibility_score += 0.08
            except:
                pass
        
        # Indeterminacy space Steenrod action
        indeterminacy_steenrod_closed = indeterminacy_space.get('steenrod_closed', True)
        if indeterminacy_steenrod_closed:
            compatibility_score += 0.12
        
        # Filtration preservation under Steenrod operations
        filtration_preserved = indeterminacy_space.get('steenrod_filtration_preserved', True)
        if filtration_preserved:
            compatibility_score += 0.08
        
        # Spectral sequence compatibility with Steenrod operations
        spectral_steenrod_compatible = indeterminacy_space.get('spectral_steenrod_compatible', True)
        if spectral_steenrod_compatible:
            compatibility_score += 0.1
        
        # Adams spectral sequence Steenrod compatibility
        adams_steenrod_compatible = await self._check_adams_steenrod_compatibility(value, indeterminacy_space)
        if adams_steenrod_compatible:
            compatibility_score += 0.09
        
        return compatibility_score > 0.7
    
