    # Advanced helper methods for algebraic structure analysis
    
    async def _compute_advanced_cup_product(self, elem1: Dict, elem2: Dict, ring: Dict) -> Dict[str, Any]:
        """Compute advanced cup product with geological considerations"""
        try:
            # Extract degrees and values
            deg1 = elem1.get('degree', 0)
            deg2 = elem2.get('degree', 0)
            val1 = elem1.get('value', 0.0)
            val2 = elem2.get('value', 0.0)
            
            # Compute geological interaction
            geological_interaction = await self._compute_geological_interaction(elem1, elem2)
            
            # Cup product value
            cup_value = geological_interaction * complex(val1) * complex(val2)
            
            # Apply sign correction for graded commutativity
            sign_correction = (-1) ** (deg1 * deg2)
            cup_value *= sign_correction
            
            return {
                'value': cup_value,
                'vector': np.array([cup_value]),
                'degree': deg1 + deg2,
                'geological_context': f"cup_product_{elem1.get('geological_context', 'unknown')}_{elem2.get('geological_context', 'unknown')}"
            }
        except:
            return {'value': 0.0, 'vector': np.array([0.0]), 'degree': 0}
    
    async def _vectors_approximately_equal(self, vec1: np.ndarray, vec2: Any, tolerance: float) -> bool:
        """Check if vectors are approximately equal"""
        try:
            if not isinstance(vec2, np.ndarray):
                if isinstance(vec2, (list, tuple)):
                    vec2 = np.array(vec2)
                else:
                    vec2 = np.array([vec2])
            
            if vec1.shape != vec2.shape:
                return False
            
            return np.allclose(vec1, vec2, atol=tolerance, rtol=tolerance)
        except:
            return False
    
    async def _verify_cup_product_steenrod_consistency(self, element: Dict, elem1: Dict, elem2: Dict, ring: Dict) -> bool:
        """Verify cup product consistency with Steenrod operations"""
        try:
            # Apply Cartan formula: Sq^n(xy) = Σ Sq^i(x) Sq^{n-i}(y)
            element_degree = element.get('degree', 0)
            
            for n in range(min(3, element_degree + 1)):
                # Compute Sq^n of the element
                sq_n_element = await self._apply_steenrod_operation(element, n, ring)
                
                # Compute Cartan formula sum
                cartan_sum = 0.0
                for i in range(n + 1):
                    sq_i_elem1 = await self._apply_steenrod_operation(elem1, i, ring)
                    sq_ni_elem2 = await self._apply_steenrod_operation(elem2, n - i, ring)
                    
                    if sq_i_elem1 and sq_ni_elem2:
                        cartan_sum += sq_i_elem1['value'] * sq_ni_elem2['value']
                
                # Check consistency
                if abs(sq_n_element['value'] - cartan_sum) > 1e-8:
                    return False
            
            return True
        except:
            return False
    
    async def _check_spectral_sequence_decomposition(self, element: Dict, d1: int, d2: int, ring: Dict) -> bool:
        """Check decomposition using spectral sequence methods"""
        try:
            # Simplified spectral sequence analysis
            element_degree = element.get('degree', 0)
            
            if d1 + d2 != element_degree:
                return False
            
            # Check E_2 page of spectral sequence
            e2_page_elements = ring.get('spectral_sequence', {}).get('E2_page', [])
            
            for e2_elem in e2_page_elements:
                if (e2_elem.get('bidegree', (0, 0)) == (d1, d2) and
                    abs(e2_elem.get('value', 0.0) - element.get('value', 0.0)) < 1e-8):
                    return True
            
            return False
        except:
            return False
    
    async def _compute_ring_square(self, element: Dict, ring: Dict) -> Optional[Dict]:
        """Compute x^2 in the ring"""
        try:
            multiplication_table = ring.get('multiplication_table', np.array([]))
            basis_elements = ring.get('basis_elements', [])
            
            if len(basis_elements) == 0:
                return None
            
            # Find element index in basis
            element_id = element.get('id', '')
            element_index = None
            
            for i, basis_elem in enumerate(basis_elements):
                if basis_elem.get('id', '') == element_id:
                    element_index = i
                    break
            
            if element_index is None:
                return None
            
            # Compute square using multiplication table
            if (multiplication_table.size > 0 and 
                element_index < multiplication_table.shape[0] and
                element_index < multiplication_table.shape[1]):
                
                square_coeffs = multiplication_table[element_index, element_index, :]
                square_value = np.sum(square_coeffs)
                
                return {
                    'value': complex(square_value),
                    'vector': square_coeffs,
                    'degree': 2 * element.get('degree', 0)
                }
            
            return None
        except:
            return None
    
    async def _is_approximately_zero(self, value: Any, tolerance: float) -> bool:
        """Check if value is approximately zero"""
        try:
            if isinstance(value, (int, float, complex)):
                return abs(value) < tolerance
            elif isinstance(value, np.ndarray):
                return np.allclose(value, 0, atol=tolerance)
            else:
                return False
        except:
            return False
    
    async def _is_scalar_multiple(self, elem1: Dict, elem2: Dict, ring: Dict) -> bool:
        """Check if elem1 is a scalar multiple of elem2"""
        try:
            val1 = elem1.get('value', 0.0)
            val2 = elem2.get('value', 0.0)
            
            if abs(val2) < 1e-15:
                return abs(val1) < 1e-15
            
            ratio = val1 / val2
            
            # Check if ratio is consistent across vector components
            vec1 = elem1.get('vector', [val1])
            vec2 = elem2.get('vector', [val2])
            
            if len(vec1) != len(vec2):
                return False
            
            for i in range(len(vec1)):
                if abs(vec2[i]) > 1e-15:
                    if abs(vec1[i] / vec2[i] - ratio) > 1e-10:
                        return False
                elif abs(vec1[i]) > 1e-15:
                    return False
            
            return True
        except:
            return False
    
    async def _compute_scalar_ratio(self, elem1: Dict, elem2: Dict) -> complex:
        """Compute scalar ratio between elements"""
        try:
            val1 = elem1.get('value', 0.0)
            val2 = elem2.get('value', 0.0)
            
            if abs(val2) > 1e-15:
                return complex(val1) / complex(val2)
            else:
                return complex(0.0)
        except:
            return complex(0.0)
    
    async def _decompose_in_basis(self, element: Dict, ring: Dict) -> Dict[str, Any]:
        """Decompose element in terms of basis elements"""
        try:
            basis_elements = ring.get('basis_elements', [])
            element_vector = element.get('vector', [element.get('value', 0.0)])
            
            if len(basis_elements) == 0:
                return {'success': False, 'reason': 'no_basis'}
            
            # Create basis matrix
            basis_matrix = []
            for basis_elem in basis_elements:
                basis_vector = basis_elem.get('vector', [basis_elem.get('value', 0.0)])
                basis_matrix.append(basis_vector)
            
            basis_matrix = np.array(basis_matrix).T
            element_vector = np.array(element_vector)
            
            # Solve linear system
            try:
                coefficients = np.linalg.lstsq(basis_matrix, element_vector, rcond=None)[0]
                
                # Create expression string
                expression_terms = []
                for i, coeff in enumerate(coefficients):
                    if abs(coeff) > 1e-10:
                        basis_id = basis_elements[i].get('id', f'basis_{i}')
                        expression_terms.append(f'{coeff:.3f}*{basis_id}')
                
                expression = ' + '.join(expression_terms) if expression_terms else '0'
                
                return {
                    'success': True,
                    'coefficients': coefficients.tolist(),
                    'basis_elements': [elem.get('id', f'basis_{i}') for i, elem in enumerate(basis_elements)],
                    'expression': expression
                }
            except:
                return {'success': False, 'reason': 'singular_system'}
        except:
            return {'success': False, 'reason': 'computation_error'}
    
