    def _compute_adem_coefficient(self, source_deg: tuple) -> float:
        """Compute Adem relation coefficient"""
        a, b = source_deg
        if a < 2 * b:
            return 0.0
        
        # Advanced Adem coefficient computation with volcanic corrections
        return math.comb(a - b - 1, 2 * b - 1) % 2
    
