    async def _compute_cohomological_dimension(self, gen: Dict[str, Any], degree: int) -> int:
        """Compute cohomological dimension using advanced homological algebra"""
        import numpy as np
        
        gen_degree = gen.get('degree', 0)
        
        # Multiple methods for computing cohomological dimension
        
        # 1. Projective dimension computation
        proj_dim = await self._compute_projective_dimension(gen)
        
        # 2. Injective dimension computation  
        inj_dim = await self._compute_injective_dimension(gen)
        
        # 3. Global dimension from ring structure
        global_dim = await self._compute_global_dimension(gen)
        
        # 4. Krull dimension computation
        krull_dim = await self._compute_krull_dimension(gen)
        
        # 5. Cohomological dimension via Ext groups
        ext_dim = await self._compute_ext_dimension(gen, degree)
        
        # 6. Spectral sequence dimension bounds
        spectral_dim = await self._compute_spectral_dimension_bound(gen, degree)
        
        # Combine different dimension computations
        dimensions = [proj_dim, inj_dim, global_dim, krull_dim, ext_dim, spectral_dim]
        valid_dimensions = [d for d in dimensions if d >= 0]
        
        if not valid_dimensions:
            return gen_degree + degree
        
        # Use minimum for conservative bound, but consider geometric constraints
        base_dimension = min(valid_dimensions)
        
        # Apply geometric and topological constraints
        manifold_dim = gen.get('manifold_dimension', 0)
        if manifold_dim > 0:
            base_dimension = min(base_dimension, manifold_dim)
        
        # Consider coefficient field
        coefficient_field = gen.get('coefficient_field', 'Z')
        if coefficient_field == 'Q':
            # Rational coefficients - dimension can be smaller
            base_dimension = min(base_dimension, gen_degree + degree - 1)
        elif coefficient_field.startswith('F_'):
            # Finite field coefficients
            p = int(coefficient_field.split('_')[1]) if '_' in coefficient_field else 2
            base_dimension = min(base_dimension, gen_degree + degree + p - 1)
        
        # Ensure reasonable bounds
        return max(0, min(base_dimension, 20))
    
    async def _compute_poincare_duality_cup_effects(self, gen: Dict[str, Any], degree: int) -> Dict[str, Any]:
        """Compute Poincaré duality effects on cup products"""
        return {
            'poincare_duality': 'PD: H^k(M) ≅ H_{n-k}(M)',
            'intersection_pairing': '⟨α, β⟩ = ∫_M α ∪ β',
            'fundamental_class': '[M] ∈ H_n(M)',
            'cap_product': 'α ∩ [M] ∈ H_{n-k}(M)'
        }
    
    def _compute_cup_indeterminacy_strength(self, gen: Dict[str, Any], complement_degree: int, target_degree: int) -> float:
        """Compute strength of cup product indeterminacy"""
        degree_factor = 1.0 / (1 + abs(target_degree - gen.get('degree', 0) - complement_degree))
